/**
 * BulkPartialSuccessResult
 *
 * Result of a bulk or import operation that reports per-resource status. `total` is how many rows/resources were processed (`successful + failed`), `successful` how many were applied (deleted, created or validated) and `failed` how many could not be processed. `failures[]` carries one item per failed row. Shape shared by every bulk endpoint of the public API (the bulk-delete endpoints emit it today). Anchored integrators before `2026-09-01` keep receiving the previous `{object, deleted, failed[{id, reason}]}` shape via `Factuarea-Version`.
 */
export type BulkPartialSuccessResult = {
    /**
     * Number of rows/resources processed (`successful + failed`).
     */
    total: number;
    /**
     * Number of rows/resources processed successfully (deleted, created or validated).
     */
    successful: number;
    /**
     * Number of rows/resources that could not be processed. Equals `failures` length.
     */
    failed: number;
    /**
     * One item per failed row/resource. Always a list (empty, never `null`, when there are no failures).
     */
    failures: Array<{
        /**
         * UUID v7 of the existing resource that could not be processed. Present for bulk operations over existing resources (e.g. bulk-delete).
         */
        id?: string;
        /**
         * 0-based position of the row within the batch. Present for new rows without a resource yet (bulk-create with `dry_run`, import CSV).
         */
        index?: number;
        /**
         * Machine-readable error code from the v1 error catalog (stable across languages). For bulk-delete: `resource_not_found` or `resource_not_deletable`.
         */
        error_code: string;
        /**
         * Human-readable reason for the failure, in Spanish (internal messages are not exposed).
         */
        error_message: string;
        /**
         * Per-field blocking issues (validate-only / bulk-create flows). Empty or absent for bulk-delete.
         */
        errors?: Array<FieldIssue>;
        /**
         * Per-field non-blocking warnings (validate-only / bulk-create flows). Empty or absent for bulk-delete.
         */
        warnings?: Array<FieldIssue>;
    }>;
};

