/**
 * ChargeRule
 *
 * A charge treatment rule of a connected Stripe account. Rules are evaluated in `position` order and the first one that matches decides whether the charge is invoiced or left out. The public `id` is the rule UUID v7.
 */
export type ChargeRule = {
    /**
     * UUID v7 of the rule. Public identity (KEY `id`).
     */
    id: string;
    /**
     * Stripe-like discriminator. Always `charge_rule`.
     */
    object: 'charge_rule';
    /**
     * Evaluation order within the account, starting at 1. Change it with `PUT /v1/companies/{company}/connected-accounts/{account}/charge-rules/order`.
     */
    position: number;
    /**
     * Condition a charge must meet for the rule to apply.
     */
    condition: {
        /**
         * Kind of condition: the charge metadata `key` equals `value`, the charge description contains `value`, or the charge comes from the payment link `value`.
         */
        type: 'metadata_equals' | 'description_contains' | 'payment_link';
        /**
         * Metadata key. Only used (and required) with `metadata_equals`; `null` otherwise.
         */
        key: string | null;
        /**
         * Value to compare against.
         */
        value: string;
    };
    /**
     * `invoice` issues the invoice (optionally with `concept` and `vat_rate`); `do_not_invoice` leaves the charge out and records it with `non_invoice_reason`.
     */
    outcome: 'invoice' | 'do_not_invoice';
    /**
     * Reason recorded for charges left out. Only with `do_not_invoice`; `null` with `invoice`.
     */
    non_invoice_reason: 'indemnity_not_subject' | 'multipurpose_voucher' | 'invoiced_elsewhere' | null;
    /**
     * Concept of the invoice line. Only with `invoice`; `null` otherwise.
     */
    concept: string | null;
    /**
     * VAT rate in percent applied to the line. Only with `invoice`; `null` otherwise.
     */
    vat_rate: number | null;
    /**
     * When the rule was created (ISO 8601).
     */
    created_at: string;
    /**
     * When the rule was last updated (ISO 8601).
     */
    updated_at: string;
};

/**
 * ChargeRuleRequest
 */
export type ChargeRuleRequest = {
    condition: {
        type: 'metadata_equals' | 'description_contains' | 'payment_link';
        key?: string | null;
        value: string;
    };
    outcome: 'invoice' | 'do_not_invoice';
    concept?: string | null;
    vat_rate?: number | null;
    non_invoice_reason?: 'indemnity_not_subject' | 'multipurpose_voucher' | 'invoiced_elsewhere' | null;
};

/**
 * Client
 *
 * A customer of your company.
 */
export type Client = {
    id: string;
    object: 'client';
    name: string;
    /**
     * Optional trade name (DBA), distinct from the legal name.
     */
    commercial_name?: string | null;
    /**
     * Spanish fiscal identifier (NIF, CIF, NIE). Structural format: NIF `^\d{8}[A-Z]$`, NIE `^[XYZ]\d{7}[A-Z]$`, CIF `^[A-Z]\d{7}[A-Z0-9]$`. AEAT control-digit (checksum) validation is enforced when the request opts in via the `Factuarea-Version` header on or after the activation version; without that opt-in the legacy permissive behaviour is preserved.
     */
    tax_id: string | null;
    /**
     * EU VAT identifier.
     */
    vat_id: string | null;
    email: string | null;
    phone: PhoneString | null;
    /**
     * Fax number (rarely used, legacy).
     */
    fax?: string | null;
    /**
     * Mobile number.
     */
    mobile?: string | null;
    /**
     * Client website.
     */
    website?: string | null;
    /**
     * B2B contact person.
     */
    contact_person?: string | null;
    /**
     * Additional emails for invoice delivery (administration, accounting). Maximum 5.
     */
    billing_emails?: Array<string>;
    address: Address;
    /**
     * Geographic coordinates of the client. `null` when not recorded.
     */
    coordinates?: {
        /**
         * Geographic latitude.
         */
        latitude: number;
        /**
         * Geographic longitude.
         */
        longitude: number;
    } | null;
    /**
     * Default discount applied to the client (percentage).
     */
    default_discount?: number | null;
    /**
     * Default VAT rate applied to the client (percentage).
     */
    default_vat_rate?: number | null;
    /**
     * Default IRPF withholding rate (percentage).
     */
    default_retention_rate?: number | null;
    /**
     * Whether the equivalence surcharge (*recargo de equivalencia*, the Spanish special VAT regime for retailers) applies to the client.
     */
    is_surcharge_subject?: boolean;
    /**
     * Bank accounts associated with the client. Empty `[]` when there are none.
     */
    bank_accounts?: Array<BankAccount>;
    /**
     * Preferred operation regime of the client for VAT / VeriFactu purposes.
     */
    preferred_operation_regime?: 'general' | 'intracomunitaria' | 'importacion_exportacion' | 'isp' | null;
    /**
     * Whether this client accumulates towards the annual Modelo 347 report (operations with third parties above the legal threshold).
     */
    accumulate_347: boolean;
    alternative_id?: AlternativeId | null;
    payment_preferences?: PaymentPreferences | null;
    /**
     * DIR3 code of the public-administration accounting office (Oficina Contable). FACe/Facturae directory code, not a foreign key. `null` for non-AAPP clients.
     */
    dir3_accounting_office: string | null;
    /**
     * DIR3 code of the public-administration managing body (Órgano Gestor). FACe/Facturae directory code, not a foreign key. `null` for non-AAPP clients.
     */
    dir3_managing_body: string | null;
    /**
     * DIR3 code of the public-administration processing unit (Unidad Tramitadora). FACe/Facturae directory code, not a foreign key. `null` for non-AAPP clients.
     */
    dir3_processing_unit: string | null;
    /**
     * External integration key (ERP/CRM/e-commerce) mapping this client to a record in a third-party system. Free-format, unique per company, distinct from the fiscal `tax_id`.
     */
    external_id?: string | null;
    /**
     * UUID v7 of the default price list assigned to the client.
     */
    default_price_list_id: string | null;
    /**
     * Snapshot of the assigned default price-list name.
     */
    default_price_list_name: string | null;
    notes: string | null;
    metadata: Metadata;
    is_active: boolean;
    created_at: string | null;
    updated_at: string | null;
};

/**
 * ClientRef
 */
export type ClientRef = {
    id: string | null;
    name: string | null;
};

/**
 * ClockActionRequest
 */
export type ClockActionRequest = {
    /**
     * Employee ID (UUID v7) clocking in or out.
     */
    employee_id: string;
    /**
     * Origin of the clock entry: `web` or `mobile`.
     */
    source: 'web' | 'mobile';
    /**
     * Clock entry timestamp in ISO 8601 (defaults to the server instant).
     */
    occurred_at?: string | null;
};

/**
 * CloseMonthlyTimeRecordRequest
 */
export type CloseMonthlyTimeRecordRequest = {
    /**
     * Year of the period to close (YYYY).
     */
    year: number;
    /**
     * Month of the period to close (1-12).
     */
    month: number;
};

/**
 * Company
 *
 * A company (tax ID) of your account, registered and operated through the `/v1/accounts/{account}/companies` endpoints. `readiness` (whether it can issue right now, with the same contract as `GET /v1/accounts/{account}/companies/{company}/issuing-readiness`) is present only when the list is requested with `include=readiness`; otherwise the key is absent.
 */
export type Company = {
    /**
     * Opaque identifier (UUID v7) of the tax ID.
     */
    id: string;
    /**
     * Always `company`.
     */
    object: 'company';
    /**
     * Commercial name of the tax ID.
     */
    name: string;
    /**
     * Legal/registered business name (razón social), or `null` if not set.
     */
    business_name: string | null;
    /**
     * Spanish fiscal identifier (NIF/CIF/NIE). Unique within your account.
     */
    tax_id: string;
    /**
     * Status of the tax ID in the account: `active` (operational), `inactive` (deactivated, data preserved, can be reactivated) or `archived` (no longer accepts operations).
     */
    status: 'active' | 'inactive' | 'archived';
    /**
     * When the tax ID entered its current `inactive` or `archived` status (ISO 8601). `null` for an `active` tax ID and for one whose change predates the lifecycle events: the date is never invented.
     */
    status_since: string | null;
    /**
     * Street address of the fiscal domicile, or `null`.
     */
    address: string | null;
    /**
     * City of the fiscal domicile, or `null`.
     */
    city: string | null;
    /**
     * Postal code of the fiscal domicile, or `null`.
     */
    postal_code: string | null;
    /**
     * Province of the fiscal domicile, or `null`.
     */
    province: string | null;
    /**
     * AEAT territorial zone of the company (`peninsula`, `canarias`, `ceuta`, `melilla`), or `null`.
     */
    country_aeat_zone: 'peninsula' | 'canarias' | 'ceuta' | 'melilla' | null;
    /**
     * Country of the fiscal domicile as recorded in the company profile (free text, up to 100 characters), or `null` when it was not set.
     */
    country: string | null;
    /**
     * Contact email, or `null`.
     */
    email: string | null;
    /**
     * Contact phone, or `null`.
     */
    phone: string | null;
    /**
     * Absolute URL of the company logo, or `null` if not set.
     */
    logo_url: string | null;
    /**
     * Paid coverage of this company as an additional tax ID of the account (ISO 8601): reactivating it before this date is free. `null` when it was never charged or the coverage expired.
     */
    paid_until: string | null;
    /**
     * Why the system suspended this `inactive` tax ID, or `null` when it is not suspended by the system (active, archived, or deactivated by the account itself). `payer_blocked`: the account paying for this managed account has its billing blocked; it resumes when the payer settles. `management_ended`: the management of this managed account ended before anyone took over the payment; it resumes when the holder of the account takes over the payment.
     */
    suspension_reason: 'payer_blocked' | 'management_ended' | null;
    /**
     * When the tax ID was registered in the account (ISO 8601).
     */
    created_at: string;
    /**
     * When the tax ID was last updated (ISO 8601), or `null`.
     */
    updated_at: string | null;
    readiness?: IssuingReadiness;
};

/**
 * CompanyCertificate
 *
 * Metadata of an FNMT (PKCS#12) certificate used to sign VeriFactu transmissions. The certificate password and binary are never exposed — only X.509 metadata.
 */
export type CompanyCertificate = {
    /**
     * UUID v7 of the certificate.
     */
    id: string;
    object: 'verifactu_certificate';
    /**
     * Tax ID (NIF) of the X.509 certificate holder.
     */
    subject_nif: string;
    /**
     * Name of the certificate holder.
     */
    subject_name: string;
    /**
     * Type of holder (individual / legal entity / representative).
     */
    subject_kind: string;
    /**
     * Certificate validity start date.
     */
    valid_from: string;
    /**
     * Certificate validity end date (expiration).
     */
    valid_to: string;
    /**
     * Whether this is the active certificate used to sign transmissions.
     */
    is_active: boolean;
    /**
     * Revocation date, or `null` if not revoked.
     */
    revoked_at: string | null;
    /**
     * Date the certificate was uploaded.
     */
    created_at: string;
};

/**
 * CompanyCreationStatus
 *
 * Provisioning lifecycle status of a tax ID (company) of the account. Poll it after registering the tax ID to know when it becomes operational.
 */
export type CompanyCreationStatus = {
    /**
     * Opaque identifier (UUID v7) of the tax ID.
     */
    id: string;
    /**
     * Always `company_creation_status`.
     */
    object: 'company_creation_status';
    /**
     * Provisioning lifecycle status: `pending`, `awaiting_payment`, `provisioning`, `active` or `failed`.
     */
    provisioning_status: 'pending' | 'awaiting_payment' | 'provisioning' | 'active' | 'failed';
    /**
     * URL to set up the payment method of the account titular; when it is saved the person returns to the Companies page of the app (`/companies`). Only present while `awaiting_payment` and for a production credential that reaches the titular company; `null` otherwise.
     */
    payment_setup_url: string | null;
    /**
     * Human-readable reason the provisioning failed. Only present when `provisioning_status` is `failed`; `null` otherwise.
     */
    failed_reason: string | null;
    /**
     * When provisioning started (ISO 8601), or `null` if not started yet.
     */
    started_at: string | null;
    /**
     * When provisioning completed (ISO 8601), or `null` if not completed yet.
     */
    completed_at: string | null;
};

/**
 * CompanyList
 *
 * Cursor-paginated list of the tax IDs of your account (`{ data, has_more, next_cursor }`).
 */
export type CompanyList = {
    /**
     * Page of tax IDs.
     */
    data: Array<Company>;
    /**
     * `true` when more companies exist beyond this page.
     */
    has_more: boolean;
    /**
     * Opaque cursor for the next page, or `null` when `has_more` is `false`.
     */
    next_cursor: string | null;
};

/**
 * CompanyRepresentation
 *
 * The representation with which your company authorizes Factuarea to remit its VeriFactu records to AEAT on its behalf: social collaboration (annex I of the Resolution of 18-12-2024) or a power of attorney registered with AEAT. There is at most ONE active representation per company; a revoked one is kept in the history and never reactivated. The custodied document is never returned.
 */
export type CompanyRepresentation = {
    /**
     * UUID v7 of the representation.
     */
    id: string;
    object: 'verifactu_representation';
    /**
     * `social_collaboration_annex_i`: the signed annex I (social collaboration). `aeat_power_of_attorney`: a power of attorney registered with AEAT.
     */
    kind: 'social_collaboration_annex_i' | 'aeat_power_of_attorney';
    /**
     * Name of the person who signed the authorization.
     */
    signer_name: string;
    /**
     * Tax ID (NIF) of the signer.
     */
    signer_tax_id: string;
    /**
     * Date on which the authorization was granted.
     */
    granted_on: string;
    /**
     * Whether the signed document (annex I or power-of-attorney proof) is custodied. The document itself never leaves the system.
     */
    has_document: boolean;
    /**
     * Reference of the power of attorney in the AEAT register, or `null`.
     */
    power_of_attorney_reference: string | null;
    /**
     * Last day of validity (YYYY-MM-DD, Europe/Madrid), or `null` when the representation does not expire.
     */
    valid_until: string | null;
    /**
     * `true` once the last day of validity has passed. An expired representation does NOT enable third-party remission any more, so register a new one before it expires (you are warned 30 and 7 days ahead and when it expires).
     */
    is_expired: boolean;
    /**
     * `true` while the representation has not been revoked, that is, it is the CURRENT one — even when it has expired. It only enables third-party remission when `is_active` is `true` AND `is_expired` is `false`.
     */
    is_active: boolean;
    /**
     * Instant of the revocation, or `null` while it is active.
     */
    revoked_at: string | null;
    /**
     * Reason recorded on revocation, or `null` while it is active.
     */
    revocation_reason: string | null;
    created_at: string;
};

/**
 * CompanySeatChargePreview
 */
export type CompanySeatChargePreview = {
    object: 'seat_charge_preview';
    /**
     * Taxable base of the proration (without VAT), in euros as a 2-decimal string.
     */
    amount: string;
    /**
     * VAT amount of the proration, in euros as a 2-decimal string.
     */
    tax_amount: string;
    /**
     * Total actually charged (`amount + tax_amount`), in euros as a 2-decimal string.
     */
    total: string;
    tax_rate: number | null;
    currency: 'EUR';
    next_invoice_date: string | null;
    requires_payment_method: boolean;
    requires_active_plan: boolean;
    included_in_trial: boolean;
    already_covered: boolean;
    is_first_seat: boolean;
    recurring_quantity: number | null;
    recurring_base_cents: number | null;
    recurring_total_cents: number | null;
    /**
     * Explicit reason for no immediate charge. A null reason never implies an Enterprise contract; negotiated_free_price preserves the acquired private seat price.
     */
    zero_reason: 'negotiated_free_price' | 'enterprise_contract' | 'trial' | 'covered' | 'no_immediate_charge' | null;
};

/**
 * CompanyStats
 *
 * Invoicing statistics of one company (tax ID) of the account in the requested period.
 */
export type CompanyStats = {
    /**
     * Always `company_stats`.
     */
    object: 'company_stats';
    /**
     * Public identifier (UUID v7) of the company, the same `id` as in `GET /v1/accounts/{account}/companies`.
     */
    company_id: string;
    /**
     * Spanish fiscal identifier (NIF/CIF/NIE) of the company.
     */
    tax_id: string;
    /**
     * Commercial name of the company.
     */
    name: string;
    /**
     * Issued invoices of the period: sent, paid and overdue. Drafts, annulled and cancelled invoices are not counted.
     */
    invoices_count: number;
    /**
     * What those invoices invoice (paid plus pending), in euros as a 2-decimal string.
     */
    total_invoiced: string;
    /**
     * The last issued invoice of the company regardless of the period, or `null` when it has not issued any yet.
     */
    last_invoice: {
        /**
         * Invoice number.
         */
        number: string;
        /**
         * Issue date (ISO 8601 date), the same name as in the invoice resource.
         */
        issued_on: string;
        /**
         * Invoice total in euros as a 2-decimal string.
         */
        total: string;
    } | null;
};

/**
 * ConfigureAbsencePolicyCarryoverRequest
 */
export type ConfigureAbsencePolicyCarryoverRequest = {
    /**
     * Carryover mode: `none` (no carryover), `capped` (with a cap) or `unlimited` (no cap).
     */
    carryover_type: 'none' | 'capped' | 'unlimited';
    /**
     * Cap of carryover days; required and positive when the mode is `capped`.
     */
    carryover_max_days?: number | null;
    /**
     * Carryover expiry month (1-12); when provided, the day is also required.
     */
    carryover_expiry_month?: number | null;
    /**
     * Carryover expiry day (1-31); when provided, the month is also required.
     */
    carryover_expiry_day?: number | null;
};

/**
 * ConfirmStorefrontCheckoutRequest
 *
 * Confirm, right after the shopper comes back from the gateway, that the payment session was really paid — and get the state of the order and its invoice. `session_id` is REQUIRED: it is the identifier the gateway itself puts in the return address, it starts with `cs_` and is at most 255 characters long. Nothing else travels in the body: neither the amount, nor the currency, nor the account, because what is being confirmed is read from the gateway and never taken from the browser. A session that cannot be verified, or one that belongs to a DIFFERENT order, changes nothing and answers with the current state of the order rather than with an error, so probing identifiers tells the caller nothing. The `Idempotency-Key` HEADER IS REQUIRED here, because a confirmation issues the invoice of the order — a fiscal document with a sequential number that can only be undone with a corrective one: the same key with the same body replays the SAME answer and leaves ONE single invoice. Confirming an order that is already paid is not an error either: it answers what it already knows.
 */
export type ConfirmStorefrontCheckoutRequest = {
    /**
     * Identifier of the payment session the gateway returns in the address the shopper comes back to. REQUIRED, starts with `cs_` and is at most 255 characters long. It is checked against the order being confirmed: a session of ANOTHER order changes nothing and the answer publishes the current state of this one, so it never confirms that some other session exists or was paid.
     */
    session_id: string;
};

/**
 * ConnectReturnDomain
 *
 * A host your account allows as the destination of the `return_url` of Stripe Connect authorizations.
 */
export type ConnectReturnDomain = {
    /**
     * Opaque identifier (UUID v7) of the return domain.
     */
    id: string;
    /**
     * Always `connect_return_domain`.
     */
    object: 'connect_return_domain';
    /**
     * The host, lower-cased and normalized: no scheme, port, path or wildcard.
     */
    domain: string;
    /**
     * Instant the domain was registered.
     */
    created_at: string;
};

/**
 * ConnectReturnDomainList
 *
 * Cursor-paginated list of the return domains of your account.
 */
export type ConnectReturnDomainList = {
    /**
     * Return domains on the current page.
     */
    data: Array<ConnectReturnDomain>;
    /**
     * Whether more pages are available after this one.
     */
    has_more: boolean;
    /**
     * Opaque cursor for the next page (pass it as `starting_after`), or `null` when `has_more` is `false`.
     */
    next_cursor: string | null;
    /**
     * Additional information about the collection.
     */
    meta: {
        /**
         * Maximum number of return domains an account can register. The list is complete once `has_more` is `false`, so `data` length against `max` tells how many slots are left.
         */
        max: number;
    };
};

/**
 * ConnectStoreV1Request
 *
 * Public REST API v1 — POST /v1/companies/{company}/stores.
 *
 * Connect an e-commerce store to your company. Required: `integration_id` (the
 * provider connection that backs the store), `provider`, `external_store_id`
 * (the identifier the provider gives to the shop) and `name`. The eight
 * settings are optional and each one falls back to its declared default, so a
 * store connected without any of them is created with automatic invoicing OFF
 * and in the `test` environment. `simplified_threshold` is expressed in EUROS
 * and capped at the legal maximum for a simplified invoice. `series_id` is a
 * series of type invoice; omit it to follow the default series of your company,
 * which is never frozen into the store. A company may connect several stores of
 * the same provider, but not the same remote shop twice.
 */
export type ConnectStoreV1Request = {
    /**
     * Identifier (UUID v7) of the provider connection that backs the store.
     */
    integration_id: string;
    /**
     * E-commerce provider of the store: `woocommerce`, `shopify` or `prestashop`.
     */
    provider: 'woocommerce' | 'shopify' | 'prestashop';
    /**
     * Identifier the provider gives to the shop; unique per provider within your company.
     */
    external_store_id: string;
    /**
     * Display name of the store, editable at any time.
     */
    name: string;
    /**
     * Series (UUID v7, type invoice) the store numbers into; omit to follow the default series of your company.
     */
    series_id?: string | null;
    /**
     * Order total, in euros, up to which the store issues a simplified invoice. Maximum 3000.00.
     */
    simplified_threshold?: number | null;
    /**
     * Whether the buyer tax ID is required for the order to be invoiced.
     */
    require_tax_id?: boolean | null;
    /**
     * Whether the prices of the store already include taxes.
     */
    prices_include_tax?: boolean | null;
    /**
     * Whether paid orders are invoiced automatically. Off unless you turn it on.
     */
    autoinvoicing_enabled?: boolean | null;
    /**
     * Whether the invoice is emailed to the buyer automatically. Off unless you turn it on.
     */
    autosend_enabled?: boolean | null;
    /**
     * Base address of the remote shop, checked against the outbound policy of your company.
     */
    remote_base_url?: string | null;
    /**
     * Environment the store reports as: `live` invoices for real, `test` discards with a typed reason.
     */
    environment?: 'live' | 'test' | null;
    /**
     * Authorize the host of `remote_base_url` as an outbound destination in the same call.
     */
    authorize_remote_host?: boolean | null;
};

/**
 * ConnectedAccount
 *
 * A connected Stripe account (Stripe Connect, multi-store) for your company. The public `id` is the account UUID v7. `external_account_id` (`acct_xxx`) is the external Stripe id, not a foreign key. `series_id` is the UUID v7 of the auto-invoicing document series (`null` means the company default series). The configuration fields are the effective per-account auto-invoicing settings.
 */
export type ConnectedAccount = {
    /**
     * UUID v7 of the connected account. Public identity (KEY `id`).
     */
    id: string;
    /**
     * Stripe-like discriminator. Always `connected_account` for this resource.
     */
    object: 'connected_account';
    /**
     * Editable display name of the connected account.
     */
    name: string;
    /**
     * External Stripe connected account id (`acct_xxx`). NOT an internal UUID nor a foreign key.
     */
    external_account_id: string;
    /**
     * Account name reported by Stripe, or `null` if unknown.
     */
    external_account_name: string | null;
    /**
     * UUID v7 of the document series used for invoices auto-created from this account. `null` means the company default series is used.
     */
    series_id: string | null;
    /**
     * Whether auto-invoicing of charges on this account is enabled. Defaults to `false`.
     */
    autoinvoicing_enabled: boolean;
    /**
     * Simplified invoice (F2) threshold in cents for this account, range `[0, 300000]` (0–3,000 €). Defaults to 40000 (400 €).
     */
    simplified_threshold_cents: number;
    /**
     * Whether a Spanish tax ID (NIF) is required for auto-invoicing on this account. Defaults to `false`.
     */
    require_nif: boolean;
    /**
     * Whether a Stripe refund (`charge.refunded`) on this account automatically generates a linked corrective invoice. Defaults to `true`.
     */
    refunds_enabled: boolean;
    /**
     * Whether Stripe subscription cycles on this account are auto-invoiced. Defaults to `false`.
     */
    subscription_autoinvoicing_enabled: boolean;
    /**
     * Default concept of the single line created for charges whose lines cannot be recovered, or `null` if not configured. Editable with `PATCH /v1/companies/{company}/connected-accounts/{account}`.
     */
    default_line_concept: string | null;
    /**
     * Optional note written in the notes of the invoices auto-created from this account, or `null` when none is configured (the default: invoices carry no note). When a charge needed a currency conversion to EUR, the conversion trace is appended to the note. Editable with `PUT`; `null` or an empty string clears it.
     */
    invoice_note: string | null;
    /**
     * How the account was linked to Stripe: `account_links` (Stripe Connect onboarding) or `stripe_app` (Stripe App). Read-only.
     */
    connection_method: 'account_links' | 'stripe_app';
    /**
     * Authorization state of the link with Stripe: `authorized`, `reauthorization_required` (the account must be linked again) or `revoked`. Read-only.
     */
    authorization_status: 'authorized' | 'reauthorization_required' | 'revoked';
    /**
     * Account status. `active` while connected; `disconnected` (terminal) after disconnecting (invoices and history are kept).
     */
    status: 'active' | 'disconnected';
    /**
     * When the account was connected (ISO 8601), or `null` if unknown.
     */
    connected_at: string | null;
};

/**
 * ConnectedAccountAuthorization
 *
 * A Stripe Connect authorization in progress for one company. Open `url` in the browser of the person who owns the Stripe account; Factuarea completes the connection when Stripe sends them back and then redirects to `return_url`.
 */
export type ConnectedAccountAuthorization = {
    /**
     * Opaque identifier (UUID v7) of the authorization. It comes back as `authorization_id` in the redirect to `return_url`.
     */
    id: string;
    /**
     * Always `connected_account_authorization`.
     */
    object: 'connected_account_authorization';
    /**
     * Stripe onboarding link to open in the browser. It is a short-lived Stripe Account Link: when it expires or has already been used, Stripe sends the person to the refresh URL of Factuarea, which renews it, so you do not need to start again. `expires_at` is not its expiry.
     */
    url: string;
    /**
     * The `https` address the person is sent back to, exactly as you sent it.
     */
    return_url: string;
    /**
     * `pending` until the person finishes in Stripe; a started authorization is always returned `pending`.
     */
    status: 'pending' | 'completed';
    /**
     * Deadline to complete the authorization (24 hours after it was started by default). After that instant the redirect to `return_url` reports an expired authorization and you must start it again. It is not the expiry of `url`.
     */
    expires_at: string;
    /**
     * Public identifier (UUID v7) of the company the Stripe account will be connected to.
     */
    company_id: string;
};

/**
 * ConsolidatedWorkforce
 *
 * A row of the consolidated workforce compliance panel of an account: the public identity of one `active` tax ID plus its time-tracking compliance summary, projected from that company’s latest monthly close without recomputation. A computed resource with no identity of its own: its `id` is the UUID v7 of the tax ID, never a record id.
 */
export type ConsolidatedWorkforce = {
    /**
     * UUID v7 of the tax ID this row belongs to (the resource has no id of its own).
     */
    id: string;
    /**
     * Trade name / legal name of the tax ID.
     */
    name: string;
    /**
     * Spanish fiscal identifier (NIF/CIF) of the tax ID.
     */
    tax_id: string;
    /**
     * true when the current (last closable) period is closed for this company.
     */
    current_period_closed: boolean;
    /**
     * Status of the current period close: `closed`, `reopened`, or `null` when the company has no close for it.
     */
    current_period_status: 'closed' | 'reopened' | null;
    /**
     * Year of the company’s latest existing monthly close, or `null` when it has none.
     */
    last_closed_year: number | null;
    /**
     * Month (1-12) of the company’s latest existing monthly close, or `null` when it has none.
     */
    last_closed_month: number | null;
    /**
     * Total balance in minutes from the snapshot of the latest close (may be negative).
     */
    total_balance_minutes: number;
    /**
     * Total overtime in minutes from the snapshot of the latest close.
     */
    total_overtime_minutes: number;
    /**
     * Number of employees in the snapshot of the latest close.
     */
    employee_count: number;
    /**
     * Account the tax ID belongs to: `{id, name}` (your own account for a tax ID of your account), or `null` when the tax ID has no account.
     */
    account: {
        /**
         * Opaque identifier (UUID v7) of the account.
         */
        id: string;
        /**
         * Visible name of the account.
         */
        name: string;
    } | null;
    /**
     * How the tax ID reaches you: `granted` (access granted to you), `provisioned` (a managed account your account provisioned) or `null` (a tax ID of your own account).
     */
    relation_origin: 'granted' | 'provisioned' | null;
    /**
     * Level you hold on the tax ID: `view` (read-only) or `operate`. For a credential, the level of its portfolio.
     */
    access_level: 'view' | 'operate';
};

