/**
 * PreviewBusinessContactImportV1Request
 */
export type PreviewBusinessContactImportV1Request = {
    /**
     * Maximum file size: 10240 kilobytes.
     */
    file: Blob | File;
    mapping?: {
        [key: string]: string;
    };
    target_roles?: Array<'customer' | 'supplier' | 'lead'>;
    conflict_strategy?: 'reject' | 'update' | 'merge';
};

/**
 * PreviewCatalogConfigurationImpactRequest
 */
export type PreviewCatalogConfigurationImpactRequest = {
    catalog_availability_mode?: 'open' | 'closed';
    configurations: Array<{
        variant_id: string | null;
        presentation_id: string | null;
        option_value_ids: Array<string> | null;
        restricts_availability: boolean;
    }>;
    presentation_ids?: Array<string>;
    variant_ids?: Array<string>;
};

/**
 * PreviewProductBaseUnitReplacementRequest
 *
 * Body of the base unit replacement preview: the new base unit, the equivalence between both units, an optional
 * price to confirm and one `keep` or `retire` decision per presentation of the product being replaced.
 */
export type PreviewProductBaseUnitReplacementRequest = {
    /**
     * Base unit of the new product. Only the nine measure units are accepted: a packaging unit (`XPK`, `XBX`…) can only be a presentation unit.
     */
    target_base_unit: 'C62' | 'KGM' | 'GRM' | 'LTR' | 'MLT' | 'MTR' | 'MTK' | 'HUR' | 'DAY';
    /**
     * Units of the CURRENT base that equal ONE unit of the NEW base (moving from kg to g,
     * 1 g = 0.001 kg, so `0.001`; from kg to count units, 1 unit = 0.5 kg gives `0.5`). Required
     * between a count unit and a measure unit; inside the same measure family it is calculated
     * and between two different measure families there is none.
     */
    equivalence?: number | null;
    /**
     * Base price of the new product per its base unit. Confirm it when the conversion loses
     * precision or there is no equivalence.
     */
    base_price?: number | null;
    /**
     * Decision per presentation of the product being replaced. Presentations you omit get the proposed decision.
     */
    presentations?: Array<{
        /**
         * Id (UUID v7) of a presentation of the product being replaced.
         */
        id: string;
        /**
         * `keep` moves the presentation to the new product; `retire` withdraws it.
         */
        decision: 'keep' | 'retire';
    }>;
};

/**
 * PreviewTaskTimeInvoiceV1Request
 */
export type PreviewTaskTimeInvoiceV1Request = {
    /**
     * Concrete time entries to invoice (mutually exclusive with `period`).
     */
    entry_ids?: Array<string>;
    /**
     * Period, by the start date of the entries (mutually exclusive with `entry_ids`).
     */
    period?: {
        from?: string;
        to?: string;
    };
    /**
     * How the invoice lines are grouped.
     */
    grouping: 'per_task' | 'per_entry' | 'single_line';
};

/**
 * PreviewTaxReportV1Request
 *
 * Compute the breakdown of a tax report without persisting any generation or file. Useful to show what is about to be declared before confirming. `303` and `347` are accepted as aliases of `modelo_303` and `modelo_347`, consistent with `POST /v1/companies/{company}/tax-reports/303` and `POST /v1/companies/{company}/tax-reports/347`.
 */
export type PreviewTaxReportV1Request = {
    type: 'modelo_303' | 'modelo_347' | 'modelo_130';
    year: number;
    quarter?: number | null;
};

/**
 * PriceList
 */
export type PriceList = {
    id: string;
    object: 'price_list';
    name: string;
    status: 'active' | 'inactive';
    currency: string;
    item_count: number;
    assigned_client_count: number;
    assigned_draft_count: number;
    items: Array<PriceListItem>;
    created_at: string;
    updated_at: string;
};

/**
 * PriceListCollection
 */
export type PriceListCollection = {
    data: Array<PriceList>;
    has_more: boolean;
    next_cursor: string | null;
};

/**
 * PriceListItem
 *
 * A price entry of a price list. Listing endpoints accept `?search=`, which filters and paginates server-side over the visible names of the target: product, variant, presentation, commercial combination and option values.
 */
export type PriceListItem = {
    id: string;
    object: 'price_list_item';
    price_list_id: string;
    product_id: string;
    variant_id: string | null;
    presentation_id: string | null;
    /**
     * The stored commercial combination the entry is priced for. `null` when the entry targets the legacy product/variant/presentation crossing or a selection signature: the three ways of naming a target are mutually exclusive. On a withdrawn entry it is read from the frozen snapshot, never from the live catalog.
     */
    configuration_id: string | null;
    /**
     * Canonical 64-hex signature of the normalized selection the entry is priced for, when it targets the selection itself instead of a stored combination. `null` otherwise. On a withdrawn entry it is read from the frozen snapshot, never from the live catalog.
     */
    selection_signature: string | null;
    product_name: string;
    variant_name: string | null;
    presentation_name: string | null;
    unit_price: string;
    currency: string;
    price_unit: string;
    /**
     * Lifecycle of the entry. `retired` means a confirmed catalog deletion withdrew it: it keeps its price as history, is excluded from price resolution, client assignment and every statistic, and is never reactivated.
     */
    status: 'active' | 'retired';
    /**
     * Why the entry was withdrawn. `product_replaced` means the product was replaced by another one with a different base unit (`POST /v1/companies/{company}/products/{product}/base-unit-replacement`): the entry keeps its price as history and, when it was transferred, a new entry for the new product carries the converted price. `null` while the entry is active.
     */
    retirement_reason: 'product_deleted' | 'variant_deleted' | 'presentation_deleted' | 'configuration_deleted' | 'option_group_deleted' | 'option_value_deleted' | 'legacy_orphan' | 'product_replaced' | null;
    /**
     * Human-readable label of `retirement_reason`, in Spanish. `null` while the entry is active.
     */
    retirement_reason_label: string | null;
    retired_at: string | null;
    /**
     * Snapshot of the target taken when the entry was withdrawn. It is read from the entry itself, never from the live catalog, so it still describes the entry after the product is gone. `null` while the entry is active.
     */
    retired_target_snapshot: RetiredPriceListTarget | null;
    created_at: string;
    updated_at: string;
};

/**
 * PriceListItemCollection
 *
 * Cursor-paginated price entries. `has_more` and `next_cursor` are computed over the FILTERED set when `?search=` is supplied, not over the whole price list.
 */
export type PriceListItemCollection = {
    data: Array<PriceListItem>;
    has_more: boolean;
    next_cursor: string | null;
};

/**
 * Product
 *
 * A product in your catalog.
 */
export type Product = {
    id: string;
    object: 'product';
    name: string;
    sku: string | null;
    price: Money;
    currency: string;
    tax_rate: TaxRateRef | null;
    /**
     * Available stock quantity with four-decimal scale.
     */
    stock: string;
    /**
     * Catalog item kind.
     */
    item_kind: 'product' | 'service';
    /**
     * UNECE base unit code. Only the nine measure units can be a base unit (`C62`, `KGM`, `GRM`, `LTR`, `MLT`, `MTR`, `MTK`, `HUR`, `DAY`); a packaging or count unit (`H87`, `XPK`, `XBX`…) can only be the unit of a presentation or a supplier offer. It cannot be edited once the product has history: see `base_unit_change` and `POST /v1/companies/{company}/products/{product}/base-unit-replacement`.
     */
    base_unit: 'C62' | 'KGM' | 'GRM' | 'LTR' | 'MLT' | 'MTR' | 'MTK' | 'HUR' | 'DAY';
    /**
     * Gross transport weight in kg per BASE unit (decimal string, up to 4 decimals, greater than 0), packaging included; `null` when unknown. Rejected with 422 `gross_weight_not_allowed` for services and for products whose base unit is a mass unit (`KGM`, `GRM`), where the weight is the quantity itself. A variant weight replaces it for that variant; a fixed presentation may declare its own weight per commercial unit.
     */
    gross_weight_kg?: string | null;
    /**
     * Whether the product participates in document-driven stock movements (invoices, delivery notes). Requires the company `stock_management` module to be enabled. Defaults to `false`.
     */
    manage_stock: boolean;
    /**
     * Product gallery images.
     */
    gallery: Array<{
        /**
         * Position of the image in the gallery (0-based).
         */
        index: number;
        /**
         * Public URL of the image.
         */
        url: string;
        /**
         * MIME type of the image (e.g. `image/jpeg`).
         */
        content_type: string;
    }>;
    /**
     * Product attached video, or `null` if there is none.
     */
    video: {
        /**
         * Public URL of the video.
         */
        url: string;
        /**
         * MIME type of the video (e.g. `video/mp4`).
         */
        content_type: string;
    } | null;
    is_active: boolean;
    /**
     * Free-text description of the product.
     */
    description: string | null;
    /**
     * Product classification tags.
     */
    tags: Array<string>;
    /**
     * Threshold below which stock is considered low, or `null` if not configured.
     */
    low_stock_threshold: string | null;
    presentation_count: number;
    variant_count: number;
    supplier_offer_count: number;
    /**
     * Number of option groups the product declares (active and inactive). Always reported, so a listing that omits `option_groups` for brevity never reads as a plain product.
     */
    option_group_count: number;
    /**
     * Number of commercial combinations the product declares (active and inactive). Matches the size of `configurations` returned by the product detail.
     */
    configuration_count: number;
    /**
     * `open` keeps the Cartesian product of active axes sellable; only configurations with `restricts_availability=true` constrain their own variant. `closed` treats all active configurations as the exact allow-list.
     */
    catalog_availability_mode: 'open' | 'closed';
    preferred_supplier_offer_id: string | null;
    presentations: Array<ProductPresentation>;
    variants: Array<ProductVariant>;
    supplier_offers: Array<SupplierProductOffer>;
    /**
     * Sellable option groups (finish, flavour, quality) with their values. Always an array; `[]` when the product declares none. Populated only when the caller asks for the configurable catalog.
     */
    option_groups: Array<ProductOptionGroup>;
    /**
     * Commercial configurations used for exact pricing and, depending on `catalog_availability_mode`, availability. In `open`, they do not restrict unless a row explicitly opts in. In `closed`, active rows form the exact allow-list; an empty active list means nothing is sellable.
     */
    configurations: Array<ProductConfiguration>;
    /**
     * Indicates whether the current stock is below the configured threshold.
     */
    is_low_stock: boolean;
    /**
     * Whether there is stock available (> 0).
     */
    is_in_stock: boolean;
    /**
     * Structured technical specifications of the product (free key-value pairs). Empty object `{}` when there are no specifications.
     */
    specifications: {
        [key: string]: unknown;
    };
    metadata: Metadata;
    /**
     * External integration key (ERP/CRM/e-commerce) mapping this product to a record in a third-party system. Free-format, unique per company, orthogonal to the catalog `sku` (a product may have both, neither, or either).
     */
    external_id?: string | null;
    created_at: string | null;
    updated_at: string | null;
    base_unit_change?: BaseUnitChange;
    replaces?: ProductReplacementLink | null;
    replaced_by?: ProductReplacementLink | null;
};

/**
 * ProductActivity
 *
 * An event in the activity timeline of a product. Groups domain events originated by changes to the product itself and by documents whose lines reference it (invoices, quotes, etc.).
 */
export type ProductActivity = {
    /**
     * Domain event type (e.g. `product.updated`, `invoice.created`).
     */
    event_type: string;
    /**
     * Human-readable description of the event in Spanish.
     */
    description: string;
    /**
     * Event metadata. Internal identifiers (PKs) are stripped; `*_uuid` values are preserved.
     */
    metadata: {
        [key: string]: unknown;
    };
    /**
     * Actor that originated the event. `{type:"user",...}` for an internal user, `{type:"api_key",...}` when performed via the public v1 API, or `null` when the event is system-generated (scheduler, periodic sweep) with no attributable actor.
     */
    performed_by: {
        /**
         * Type of actor that originated the event: `user` for a human in the internal app, `api_key` for an action performed through the public v1 API.
         */
        type: 'user' | 'api_key';
        /**
         * UUID v7 of the actor: the user when `type=user`, or the API key when `type=api_key`.
         */
        id: string;
        /**
         * Actor name at the time of the event: the user name or the API key name. `null` if it could not be resolved.
         */
        name: string | null;
    } | null;
    /**
     * When the event occurred (ISO 8601).
     */
    created_at: string;
};

/**
 * ProductConfiguration
 *
 * A valid commercial combination of a product: an optional variant, an optional presentation and a canonical set of option values.
 */
export type ProductConfiguration = {
    id: string;
    object: 'product_configuration';
    product_id: string;
    /**
     * Visible label composed from variant + presentation + values. It is not a stored column: the historical name is frozen by the document line, not by the catalog. It is also the text the price-list `search` filter matches.
     */
    name: string;
    variant_id: string | null;
    variant_name: string | null;
    presentation_id: string | null;
    presentation_name: string | null;
    /**
     * Canonical, order-independent signature of variant + presentation + option values. Unique per product.
     */
    signature: string;
    /**
     * FINAL price per commercial unit. When set it ALREADY absorbs the adjustments of its option values: they are not added again.
     */
    commercial_price: string | null;
    active: boolean;
    /**
     * Only used in `open` mode. When true, this row constrains the named variant; omitted presentation/options are wildcards. False means the row is pricing/identity only.
     */
    restricts_availability: boolean;
    options: Array<ProductConfigurationOption>;
};

/**
 * ProductConfigurationOption
 *
 * One chosen option inside a commercial combination.
 */
export type ProductConfigurationOption = {
    object: 'product_configuration_option';
    group_id: string;
    group_name: string;
    value_id: string;
    value_name: string;
    price_adjustment: string | null;
};

/**
 * ProductOptionGroup
 *
 * A group of sellable options of a product (finish, flavour, quality). Each group accepts a single value per line; multiple selection is out of scope.
 */
export type ProductOptionGroup = {
    id: string;
    object: 'product_option_group';
    product_id: string;
    name: string;
    /**
     * Whether a value of this group must be chosen to confirm a line.
     */
    required: boolean;
    position: number;
    /**
     * Scope of the group: `null` means it applies to the whole product; when set, it is the id of a variant or a presentation of the same product and the group only takes part in selections including it.
     */
    scope_id: string | null;
    active: boolean;
    values: Array<ProductOptionValue>;
};

/**
 * ProductOptionValue
 *
 * A selectable value inside an option group.
 */
export type ProductOptionValue = {
    id: string;
    object: 'product_option_value';
    name: string;
    /**
     * Display order inside its group.
     */
    position: number;
    /**
     * Additive adjustment PER COMMERCIAL UNIT. `null` means "this value does not change the price", which is NOT the same as `"0.0000"`.
     */
    price_adjustment: string | null;
    /**
     * Whether the value is still selectable. An inactive value keeps naming historical document lines.
     */
    active: boolean;
};

/**
 * ProductPresentation
 */
export type ProductPresentation = {
    id: string;
    object: 'product_presentation';
    product_id: string;
    name: string;
    mode: 'fixed' | 'variable_measure';
    /**
     * UN/ECE code of the commercial unit of the presentation. The nine measure units can also be a base unit; the thirteen count and packaging units (`H87` piece, `XPK` pack, `XBX` box, …) are valid only here and in supplier offers. It must be expressible over the base unit of the product: a packaging unit needs a declared equivalence (`conversion_factor` or `nominal_base_quantity`), a measure unit must belong to the same family as the base; otherwise 422 `unit_not_expressible`.
     */
    unit: 'C62' | 'KGM' | 'GRM' | 'LTR' | 'MLT' | 'MTR' | 'MTK' | 'HUR' | 'DAY' | 'H87' | 'XPK' | 'XBX' | 'XDS' | 'XBG' | 'XBO' | 'XDJ' | 'XCA' | 'XTB' | 'XCI' | 'XJY' | 'XEN' | 'XCS';
    conversion_factor: string | null;
    nominal_base_quantity: string | null;
    barcode: string | null;
    /**
     * Own gross transport weight in kg per COMMERCIAL unit (decimal string, up to 4 decimals, greater than 0), packaging included; it overrides any derivation from the product or variant weight. `null` when the presentation declares none. Rejected with 422 `gross_weight_not_allowed` on `variable_measure` presentations.
     */
    gross_weight_kg?: string | null;
    /**
     * Own price PER COMMERCIAL UNIT, or `null` when the presentation declares none. Orthogonal to `conversion_factor`, which converts QUANTITY and is never reused as a price multiplier: a 3.5 kg tub priced at 50.00 is worth 50.00 per tub.
     */
    commercial_price_override: string | null;
    /**
     * Technical specifications OWN to this presentation (informational, not selectable). Empty object `{}` when there are none. The effective sheet combines product < variant < presentation and is composed by the aggregate.
     */
    specifications: {
        [key: string]: unknown;
    };
    active: boolean;
};

/**
 * ProductRef
 */
export type ProductRef = {
    id: string;
    name: string | null;
};

/**
 * ProductReplacementLink
 *
 * The OTHER end of a base unit replacement: on `replaces`, the old product the current one replaced; on `replaced_by`, the new product that replaced the current one.
 */
export type ProductReplacementLink = {
    /**
     * Id of the other product.
     */
    id: string;
    name: string;
    /**
     * Base unit of the other product.
     */
    base_unit: 'C62' | 'KGM' | 'GRM' | 'LTR' | 'MLT' | 'MTR' | 'MTK' | 'HUR' | 'DAY';
    replaced_at: string;
    /**
     * Old base units per ONE new base unit, decimal string with scale 6. `null` between measure families with no declared equivalence.
     */
    equivalence: string | null;
    /**
     * Stock moved to the new product, decimal string with scale 4, ALWAYS in the unit of the NEW product.
     */
    stock_transferred: string;
};

/**
 * ProductSalesAnalytics
 */
export type ProductSalesAnalytics = {
    /**
     * Exact quantity sold, represented as a decimal string.
     */
    units_sold: string;
    /**
     * Revenue of the product (EUR), as a 2-decimal string.
     */
    total_revenue: string;
    invoices_count: number;
    month_over_month_delta_percent: number;
    trend: Array<string>;
    trend_labels: Array<string>;
    last_buyer: {
        name: string;
        initials: string;
        invoice_number: string;
        invoice_date: string;
    } | null;
    activity: Array<{
        id: string;
        kind: string;
        title: string;
        detail: string;
        occurred_at: string;
    }>;
};

/**
 * ProductStats
 *
 * Aggregated summary of the product catalog of the authenticated company: total, active, out of stock and low stock. Returned by `GET /v1/companies/{company}/products/stats`.
 */
export type ProductStats = {
    /**
     * Total number of products registered in the company.
     */
    total_products: number;
    /**
     * Products marked as active.
     */
    active_products: number;
    /**
     * Products with no stock available (stock = 0).
     */
    out_of_stock_count: number;
    /**
     * Products whose stock is below the configured threshold.
     */
    low_stock_count: number;
};

/**
 * ProductVariant
 */
export type ProductVariant = {
    id: string;
    object: 'product_variant';
    product_id: string;
    name: string;
    sku: string | null;
    barcode: string | null;
    base_price_override: string | null;
    unit_cost_override: string | null;
    /**
     * Own gross transport weight in kg per BASE unit (decimal string, up to 4 decimals, greater than 0) that replaces the product weight for this variant; `null` inherits the product weight. Rejected with 422 `gross_weight_not_allowed` when the product base unit is a mass unit.
     */
    gross_weight_kg?: string | null;
    manage_stock: boolean;
    stock: string;
    low_stock_threshold: string | null;
    /**
     * Technical specifications OWN to this variant (informational, not selectable). Empty object `{}` when there are none. `base_price_override` stays PER BASE UNIT, unlike a presentation price, which is per commercial unit.
     */
    specifications: {
        [key: string]: unknown;
    };
    active: boolean;
};

/**
 * Proforma
 *
 * A proforma invoice that can be converted to a final invoice.
 */
export type Proforma = {
    id: string;
    object: 'proforma';
    number: string;
    series: SeriesRef;
    client: ClientRef;
    /**
     * Proforma lifecycle status (draft, accepted, rejected, cancelled, expired, converted).
     */
    status: string;
    /**
     * UUID of the price list selected for this document.
     */
    price_list_id: string | null;
    /**
     * Price-list name snapshot frozen on the document.
     */
    price_list_name: string | null;
    issued_on: string;
    valid_until: string | null;
    /**
     * Number of validity days of the proforma since its issuance. `null` if not applicable.
     */
    validity_days: number | null;
    /**
     * Free reference of the document (e.g. the customer order number).
     */
    reference: string | null;
    /**
     * VAT operation regime of the proforma (`general`, `intracomunitaria`, `importacion_exportacion`, `isp`).
     */
    operation_regime: string;
    /**
     * UUID v7 of the invoice this proforma was converted into, if applicable.
     */
    converted_to_id: string | null;
    /**
     * Human-readable number of the invoice this proforma was converted into (e.g. "F-2026-00042"). `null` if not converted.
     */
    converted_invoice_number: string | null;
    subtotal: string;
    /**
     * NET aggregate of the header taxes: `total_vat + total_surcharge − total_retention`. It is the amount that, added to `subtotal`, yields `total` (`total === subtotal + taxes_total`), so it must NOT be combined with `total_retention`: subtracting the withholding again on top of the aggregate produces a false total (4,320.00 + 259.20 − 648.00 = 3,931.20 against a real total of 4,579.20). It is NOT the VAT figure of the Spanish Modelo 303 — read `total_vat` for that. Beware that on an expense the same field name carries a DIFFERENT meaning (VAT only), which is why the identity that holds across all five document families is the explicit one: `total === subtotal + total_vat + total_surcharge − total_retention`.
     */
    taxes_total: string;
    /**
     * Sum of the VAT of all lines.
     */
    total_vat: string;
    /**
     * Sum of the withholding (IRPF) of all lines.
     */
    total_retention: string;
    /**
     * Sum of the equivalence surcharge of all lines.
     */
    total_surcharge: string;
    /**
     * Total of the document. Two equivalent ways to reconstruct it from the published amounts, and only these two: the EXPLICIT one, identical in the five document families - `total = subtotal + total_vat + total_surcharge - total_retention` - or the AGGREGATE one, specific to the sales-side families - `total = subtotal + taxes_total`. NEVER reconstruct it as `subtotal + taxes_total - total_retention`: `taxes_total` ALREADY has the withholding netted out, so that combination subtracts it twice and yields a false total (4,320.00 + 259.20 - 648.00 = 3,931.20 against a real 4,579.20).
     */
    total: string;
    /**
     * Shipping cost, expressed WITH VAT INCLUDED, added to the amount to pay. It is not part of `subtotal`, `total_vat` or `total`. When the proforma is converted to an invoice it becomes a "Gastos de envío" line whose base is `shipping_cost / (1 + r)` with VAT `r`, so the invoice total equals `total_with_shipping`.
     */
    shipping_cost: string;
    /**
     * Final total including the shipping cost (= total + shipping_cost). The invoice generated from the proforma has exactly this total.
     */
    total_with_shipping: string;
    currency: string;
    /**
     * Preferred payment method (backing value of the Shared enum `PaymentMethod`, e.g. `bank_transfer`).
     */
    payment_method: string | null;
    /**
     * Payment term in days (Net X). Valid range: 0-365.
     */
    payment_terms_days: number | null;
    /**
     * Delivery terms, free-form text.
     */
    delivery_terms: string | null;
    /**
     * Estimated delivery date (YYYY-MM-DD).
     */
    estimated_delivery_date: string | null;
    notes: string | null;
    /**
     * Terms and conditions rendered in the proforma PDF.
     */
    terms_and_conditions: string | null;
    /**
     * External integration key (ERP/CRM/e-commerce) mapping this document to a record in a third-party system. Free-format, unique per company, filterable via `?external_id=`. `null` when not set. Persistent synchronization key, independent of the request-level `Idempotency-Key`.
     */
    external_id: string | null;
    lines: Array<ProformaLine>;
    metadata: Metadata;
    /**
     * Free classification tags (lowercase slugs `[a-z0-9-]`, ≤ 40 chars each, ≤ 30 tags). Filterable via `?tags[in]=tag1,tag2` (JSON_CONTAINS, OR semantics). Empty `[]` when there are none.
     */
    tags: Array<string>;
    /**
     * Ordered list of typed custom fields `[{field, value}]` (≤ 50). Distinct from `metadata` (a free key→value map): use `custom_fields` for structured, display-oriented integration metadata. Empty `[]` when there are none.
     */
    custom_fields: Array<CustomField>;
    /**
     * Expiration date of the shareable public link, or `null` if unlimited.
     */
    link_expires_at: string | null;
    /**
     * Indicates whether the shareable public link is currently active.
     */
    link_is_active: boolean;
    created_at: string;
    updated_at: string;
};

/**
 * ProformaLine
 *
 * A line item on a proforma.
 */
export type ProformaLine = {
    object: 'proforma_line';
    description: string | null;
    /**
     * Optional secondary description rendered below the line concept on document PDFs.
     */
    additional_description: string | null;
    product: ProductRef | null;
    quantity: number;
    /**
     * Unit price as a decimal STRING with the 4-decimal scale of its column (e.g. `"0.0125"`, `"100.0000"`): it is returned exactly as it was accepted and stored, so reading a line and sending it back never changes its price. Derived amounts (`subtotal`, `taxes`, `total`) keep 2 decimals.
     */
    unit_price: string;
    tax_rate: number;
    /**
     * IRPF withholding percentage applied to the line (0–100). Default 0. Its amount is already aggregated into `taxes`.
     */
    retention_rate: number;
    /**
     * Equivalence surcharge (recargo de equivalencia) percentage applied to the line (0–100). Default 0. Its amount is already aggregated into `taxes`.
     */
    surcharge_rate: number;
    discount_percent: number;
    subtotal: string;
    taxes: string;
    total: string;
    /**
     * Indirect tax regime of the line: the per-document override (`iva`/`igic`/`ipsi`) when the user set it (precedence override>zone), otherwise `null` (derived from the establishment AEAT zone). Writable per-document input on create/update; the document must be homogeneous (a single non-null regime across all lines, 422 otherwise).
     */
    indirect_tax_regime?: 'iva' | 'igic' | 'ipsi' | null;
    variant: {
        id: string;
        name: string | null;
    } | null;
    presentation: {
        id: string;
        name: string | null;
        mode: string | null;
    } | null;
    item_kind: string | null;
    commercial_unit_code: 'C62' | 'KGM' | 'GRM' | 'LTR' | 'MLT' | 'MTR' | 'MTK' | 'HUR' | 'DAY' | 'H87' | 'XPK' | 'XBX' | 'XDS' | 'XBG' | 'XBO' | 'XDJ' | 'XCA' | 'XTB' | 'XCI' | 'XJY' | 'XEN' | 'XCS' | null;
    base_unit_code: 'C62' | 'KGM' | 'GRM' | 'LTR' | 'MLT' | 'MTR' | 'MTK' | 'HUR' | 'DAY' | null;
    conversion_factor: string | null;
    base_quantity: string | null;
    price_list_id: string | null;
    price_list_name: string | null;
    price_source: string | null;
    price_unit_code: 'C62' | 'KGM' | 'GRM' | 'LTR' | 'MLT' | 'MTR' | 'MTK' | 'HUR' | 'DAY' | 'H87' | 'XPK' | 'XBX' | 'XDS' | 'XBG' | 'XBO' | 'XDJ' | 'XCA' | 'XTB' | 'XCI' | 'XJY' | 'XEN' | 'XCS' | null;
    /**
     * Pieces the customer asked for on a variable-weight line sold by count (decimal string, scale 4, greater than 0), e.g. `"4.0000"` for four pieces weighing `quantity` kg in total. Informational: the line is charged and the stock is discounted by `quantity` (the real weight), never by the pieces. `null` on any other line. Only accepted on a `variable_measure` presentation whose unit is a count unit.
     */
    counted_quantity: string | null;
    /**
     * UN/ECE code of the count unit of `counted_quantity` (`H87` piece, `XPK` pack…). `null` exactly when `counted_quantity` is `null`.
     */
    counted_unit: 'H87' | 'XPK' | 'XBX' | 'XDS' | 'XBG' | 'XBO' | 'XDJ' | 'XCA' | 'XTB' | 'XCI' | 'XJY' | 'XEN' | 'XCS' | null;
    /**
     * Commercial combination frozen on the line, or `null` when the line was not sold or bought through one (legacy product, manual line).
     */
    configuration: {
        id: string;
        name: string | null;
        signature: string | null;
    } | null;
    /**
     * Configurable options frozen on the line, in printing order. Always an array, `[]` included.
     */
    options: Array<{
        group: {
            id: string;
            name: string | null;
        };
        value: {
            id: string;
            name: string | null;
        };
        /**
         * Adjustment of the chosen value per commercial unit. `null` means the value does not change the price — NOT the same as adjusting by `0`.
         */
        price_adjustment: string | null;
        /**
         * Whether that amount was actually ADDED to the unit price. `false` when an exact price (price-list entry, combination price or a manually typed unit price) already absorbed it.
         */
        applied: boolean;
    }>;
    /**
     * Monetary semantics of the resolved price: `per_base_unit` (product/variant own price, converted once by the presentation factor) or `per_commercial_unit` (presentation, combination or price-list entry, never converted). `null` on a line with no catalog price context.
     */
    price_semantics: 'per_base_unit' | 'per_commercial_unit' | null;
    /**
     * Sum of the adjustments of the chosen option values, as a decimal string. Informational when an exact price already absorbed them.
     */
    price_adjustment_total: string | null;
    /**
     * TRI-STATE, and `null` is NOT `false`. `true`: the resolved price already includes the option adjustments. `false`: they were added on top. `null`: it could not be determined — the assembler refuses such a line with 422 rather than risking charging the adjustments twice, so `null` only ever reaches a reader on a legacy line with no configurable options at all.
     */
    option_adjustments_absorbed: boolean | null;
};

/**
 * ProformaStats
 *
 * Aggregated summary of the proformas of the authenticated company: total, accumulated amount, breakdown by status (with count and amount), conversion-to-invoice ratio, those about to expire and average value. Returned by `GET /v1/companies/{company}/proformas/stats`.
 */
export type ProformaStats = {
    /**
     * Total number of recorded proformas.
     */
    total_count: number;
    /**
     * Aggregate amount of the proformas (EUR), as a 2-decimal string.
     */
    total_amount: string;
    /**
     * Breakdown by status. Keys: `draft`, `accepted`, `rejected`, `cancelled`, `expired`, `converted`.
     */
    by_status: {
        [key: string]: {
            /**
             * Number of proformas in this state.
             */
            count: number;
            /**
             * Aggregate amount of the proformas in this status (EUR), as a 2-decimal string.
             */
            total: string;
        };
    };
    /**
     * Conversion-to-invoice ratio (invoiced proformas / total), as a percentage from 0 to 100 with up to 2 decimals.
     */
    conversion_rate: number;
    /**
     * Proformas whose `valid_until` date expires in the coming days.
     */
    expiring_soon: number;
    /**
     * Average value of the proformas (EUR), as a 2-decimal string.
     */
    average_value: string;
};

/**
 * Project
 *
 * A task project of your company: its board columns hold the tasks, and its key (`DEV`) prefixes their keys (`DEV-12`).
 */
export type Project = {
    /**
     * UUID v7 of the project.
     */
    id: string;
    /**
     * Stripe-like discriminator. Always `project` for this resource.
     */
    object: 'project';
    /**
     * Project key, unique in your company. Prefixes the key of every task (`DEV-12`).
     */
    key: string;
    /**
     * Project name.
     */
    name: string;
    /**
     * Icon of the project, from the task icon catalog.
     */
    icon: string;
    /**
     * Free description of the project, or `null`.
     */
    description: string | null;
    /**
     * Position of the project in the list shown in the app.
     */
    position: number;
    /**
     * `true` when the project is archived (read-only, no new tasks).
     */
    is_archived: boolean;
    /**
     * When the project was archived, or `null`.
     */
    archived_at: string | null;
    /**
     * UUID of the contact invoiced by default for the logged time, or `null`.
     */
    billing_contact_id: string | null;
    /**
     * Default hourly rate (decimal string, before taxes) used to invoice the logged time, or `null`.
     */
    billing_hourly_rate: string | null;
    /**
     * UUID of the product used for the invoice lines of logged time, or `null`.
     */
    billing_product_id: string | null;
    /**
     * Task statistics of the project.
     */
    stats: {
        /**
         * Tasks of the project, archived ones included.
         */
        total_tasks: number;
        /**
         * Completed tasks.
         */
        completed_tasks: number;
        /**
         * Completed tasks over total, as a whole percentage.
         */
        completion_percentage: number;
        /**
         * Earliest due date among the open tasks, or `null`.
         */
        next_due_on: string | null;
    };
    /**
     * Creation timestamp.
     */
    created_at: string;
    /**
     * Last update timestamp.
     */
    updated_at: string;
};

/**
 * ProjectColumn
 *
 * A column of a project board. Tasks in a final column (`is_final`) are completed.
 */
export type ProjectColumn = {
    /**
     * UUID v7 of the column.
     */
    id: string;
    /**
     * Stripe-like discriminator. Always `project_column` for this resource.
     */
    object: 'project_column';
    /**
     * UUID of the project the column belongs to.
     */
    project_id: string;
    /**
     * Column name.
     */
    name: string;
    /**
     * Stable identifier derived from the name, unique in the project (`planned` and `archived` are reserved).
     */
    slug: string;
    /**
     * Icon of the column, or `null`.
     */
    icon: string | null;
    /**
     * Color of the column from the task palette, or `null`.
     */
    color: string | null;
    /**
     * `true` when moving a task here completes it.
     */
    is_final: boolean;
    /**
     * Position of the column on the board.
     */
    position: number;
};

/**
 * ProjectColumnList
 *
 * Page of columns (the whole board, never more than one page) (`{ data, has_more, next_cursor }`).
 */
export type ProjectColumnList = {
    data: Array<ProjectColumn>;
    /**
     * `true` when there are more objects after this page.
     */
    has_more: boolean;
    /**
     * Value to pass as `starting_after` to get the next page (the `id` of the last object), or `null` when `has_more` is `false`.
     */
    next_cursor: string | null;
};

/**
 * ProjectCustomField
 *
 * A custom field defined for the tasks of a project.
 */
export type ProjectCustomField = {
    /**
     * UUID v7 of the custom field.
     */
    id: string;
    /**
     * Stripe-like discriminator. Always `project_custom_field` for this resource.
     */
    object: 'project_custom_field';
    /**
     * UUID of the project.
     */
    project_id: string;
    /**
     * Field name, unique in the project.
     */
    name: string;
    /**
     * Value type of the field.
     */
    type: 'text' | 'number' | 'date' | 'dropdown' | 'boolean' | 'multiselect';
    /**
     * `true` when every task of the project must have a value.
     */
    required: boolean;
    /**
     * Value given to new tasks, serialized as a string (a JSON array for `multiselect`), or `null`.
     */
    default_value: string | null;
    /**
     * Allowed values for `dropdown` and `multiselect`; empty for the other types.
     */
    options: Array<string>;
    /**
     * Display order of the field.
     */
    position: number;
};

/**
 * ProjectCustomFieldList
 *
 * Page of custom fields (all of them, never more than one page) (`{ data, has_more, next_cursor }`).
 */
export type ProjectCustomFieldList = {
    data: Array<ProjectCustomField>;
    /**
     * `true` when there are more objects after this page.
     */
    has_more: boolean;
    /**
     * Value to pass as `starting_after` to get the next page (the `id` of the last object), or `null` when `has_more` is `false`.
     */
    next_cursor: string | null;
};

/**
 * ProjectList
 *
 * Page of projects (`{ data, has_more, next_cursor }`).
 */
export type ProjectList = {
    data: Array<Project>;
    /**
     * `true` when there are more objects after this page.
     */
    has_more: boolean;
    /**
     * Value to pass as `starting_after` to get the next page (the `id` of the last object), or `null` when `has_more` is `false`.
     */
    next_cursor: string | null;
};

/**
 * ProjectTasksExport
 *
 * JSON export of the tasks of a project (`factuarea.tasks.v1`), importable with `POST /v1/companies/{company}/projects/{project}/tasks/import`.
 */
export type ProjectTasksExport = {
    /**
     * Stripe-like discriminator. Always `project_tasks_export` for this resource.
     */
    object: 'project_tasks_export';
    /**
     * UUID of the exported project.
     */
    project_id: string;
    /**
     * Format of the document. Always `factuarea.tasks.v1` today.
     */
    format: string;
    /**
     * When the export was generated.
     */
    exported_at: string | null;
    /**
     * The project: key, name, icon, description and its columns.
     */
    project: {
        [key: string]: unknown;
    };
    /**
     * Labels used by the exported tasks.
     */
    labels: Array<{
        [key: string]: unknown;
    }>;
    /**
     * Custom field definitions of the project.
     */
    custom_fields: Array<{
        [key: string]: unknown;
    }>;
    /**
     * Every task with its column, priority, dates, labels, custom field values and comments.
     */
    tasks: Array<{
        [key: string]: unknown;
    }>;
};

/**
 * ProjectTasksImport
 *
 * Report of a synchronous task import. The API imports at most 200 tasks per call and never creates background runs, so the report has no `mode` or `run_id`.
 */
export type ProjectTasksImport = {
    /**
     * Stripe-like discriminator. Always `project_tasks_import` for this resource.
     */
    object: 'project_tasks_import';
    /**
     * UUID of the project the tasks were imported into.
     */
    project_id: string;
    /**
     * Tasks in the document.
     */
    total: number;
    /**
     * Tasks created.
     */
    created: number;
    /**
     * Tasks that could not be created.
     */
    failed: number;
    /**
     * Non-blocking adjustments (an unknown member left unassigned, a label created…). Only the first 200 are listed: see `warnings_truncated` and `warnings_total`.
     */
    warnings: Array<{
        /**
         * Position of the task in the document, or `null` for a document-level warning.
         */
        index: number | null;
        /**
         * Warning, in Spanish.
         */
        message: string;
    }>;
    /**
     * `true` when the document produced more than 200 warnings and only the first 200 are in `warnings`.
     */
    warnings_truncated: boolean;
    /**
     * Number of warnings the import produced, including those left out of `warnings`.
     */
    warnings_total: number;
    /**
     * Outcome per task of the document.
     */
    tasks: Array<{
        /**
         * Position of the task in the document.
         */
        index: number | null;
        /**
         * UUID of the created task, or `null` when it failed.
         */
        id: string | null;
        /**
         * Key of the created task (`DEV-12`), or `null` when it failed.
         */
        key: string | null;
        /**
         * Why the task was not created, in Spanish, or `null`.
         */
        error: string | null;
    }>;
};

/**
 * ProjectTimeSummary
 *
 * Time logged on the tasks of a project, optionally limited to a date range.
 */
export type ProjectTimeSummary = {
    /**
     * Stripe-like discriminator. Always `project_time_summary` for this resource.
     */
    object: 'project_time_summary';
    /**
     * UUID of the project.
     */
    project_id: string;
    /**
     * First day of the range, or `null` when not limited.
     */
    from: string | null;
    /**
     * Last day of the range, or `null` when not limited.
     */
    to: string | null;
    /**
     * Logged seconds.
     */
    total_seconds: number;
    /**
     * Logged seconds marked billable.
     */
    billable_seconds: number;
    /**
     * Billable seconds already invoiced.
     */
    invoiced_seconds: number;
    /**
     * Billable seconds not yet invoiced.
     */
    pending_seconds: number;
    /**
     * Breakdown per task.
     */
    by_task: Array<{
        /**
         * UUID of the task.
         */
        task_id: string;
        /**
         * Task key.
         */
        key: string;
        /**
         * Task title.
         */
        title: string;
        total_seconds: number;
        billable_seconds: number;
        invoiced_seconds: number;
        pending_seconds: number;
    }>;
    /**
     * Breakdown per member.
     */
    by_user: Array<{
        /**
         * UUID of the member, or `null` when the user no longer exists.
         */
        user_id: string | null;
        /**
         * Member name.
         */
        name: string | null;
        total_seconds: number;
        billable_seconds: number;
    }>;
};

/**
 * ProvisionManagedAccountV1Request
 *
 * Provision a managed account for one of your clients. Required: `external_ref` (your own reference, unique per provider: repeating it returns the same account), `plan` (`emprendedor`, `empresario` or `integral`), `tax_id` (Spanish tax ID) and `legal_name`. `access_level` is the level your account keeps on it (`none` by default). `owner_email` is required with a live key and whenever `send_email` is `true`; `send_email` is `false` by default, so the claim voucher comes back ONCE in the response for you to deliver. The rest of the fiscal profile (`display_name`, address, `language`) is optional. The provider is always the account of the key and never comes from the body; the environment of the new account is the one of the key.
 */
export type ProvisionManagedAccountV1Request = {
    /**
     * Your own reference for the account (up to 128 characters), unique per provider. Provisioning it again returns the same account (200) without a new voucher.
     */
    external_ref: string;
    /**
     * Plan of the managed account: `emprendedor`, `empresario` or `integral`. `enterprise` returns 422 `managed_account_plan_not_self_serve`.
     */
    plan: 'emprendedor' | 'empresario' | 'integral' | 'enterprise';
    /**
     * Access level your account keeps on the managed account: `none` (default, provisioning only), `view` (read-only) or `operate`.
     */
    access_level?: 'none' | 'view' | 'operate';
    /**
     * Spanish tax identifier (NIF, CIF or NIE) of the managed account.
     */
    tax_id: string;
    /**
     * Legal name of the managed account.
     */
    legal_name: string;
    /**
     * Visible name of the account and of its tax ID; without it, the legal name.
     */
    display_name?: string | null;
    /**
     * Fiscal address.
     */
    address?: string | null;
    /**
     * City of the fiscal address.
     */
    city?: string | null;
    /**
     * Postal code (derives the AEAT zone).
     */
    postal_code?: string | null;
    /**
     * Province.
     */
    province?: string | null;
    /**
     * Country.
     */
    country?: string | null;
    /**
     * Language of the account and of its claim voucher: `es` (default), `en` or `ca`.
     */
    language?: 'es' | 'en' | 'ca' | null;
    /**
     * Email of the holder of the account. Required with a live key and whenever `send_email` is `true`.
     */
    owner_email?: string | null;
    /**
     * Email the claim link to `owner_email` (`true`) or return the voucher once in the response (`false`, default).
     */
    send_email?: boolean;
};

/**
 * ProvisioningUsage
 *
 * Provisioning usage of your account as a provider: its managed accounts with the management in force, its managed account limit and what it pays for them on top of their fee.
 */
export type ProvisioningUsage = {
    /**
     * Always `provisioning_usage`.
     */
    object: 'provisioning_usage';
    /**
     * Managed accounts with the management in force, by environment. Test ones never count towards `limit`.
     */
    managed_accounts: {
        live: number;
        test: number;
    };
    /**
     * Maximum number of live managed accounts of your account.
     */
    limit: number;
    /**
     * Live managed accounts that still fit within `limit` (never negative).
     */
    remaining: number;
    /**
     * Live managed accounts with the management in force, by plan. Every plan of the catalog is always present (0 when there is none).
     */
    managed_accounts_by_plan: {
        emprendedor: number;
        empresario: number;
        integral: number;
        enterprise: number;
        [key: string]: number;
    };
    /**
     * Additional tax IDs of your managed accounts that your account pays.
     */
    provider_paid_additional_nifs: number;
    /**
     * Employee seats of your managed accounts that your account pays.
     */
    provider_paid_employee_seats: number;
};

/**
 * PublicDocumentStatus
 */
export type PublicDocumentStatus = {
    value: string;
    label: string;
    color: string;
};

/**
 * PublicLink
 *
 * Represents the state of the shareable public link of a document (quote/invoice/proforma/delivery_note). `url` is the absolute URL ready to send to the client; `enabled` indicates whether it is active; `expires_at` the deadline (`null` = unlimited); `max_days` the maximum allowed when extending it.
 */
export type PublicLink = {
    object: 'public_link';
    /**
     * Absolute URL of the public link to share with the client.
     */
    url: string;
    /**
     * UUID v7 of the document the link points to.
     */
    id: string;
    /**
     * Indicates whether the public link is currently active.
     */
    enabled: boolean;
    /**
     * Expiration date/time of the link, or `null` if it does not expire.
     */
    expires_at: string | null;
    /**
     * Maximum number of days allowed when extending the link validity (business limit).
     */
    max_days: number;
};

/**
 * PurchaseInvoice
 *
 * An invoice received from a supplier.
 */
export type PurchaseInvoice = {
    id: string;
    object: 'purchase_invoice';
    /**
     * The number assigned by the supplier on their invoice. `null` for a simplified expense ticket (`is_simplified`) with no supplier number.
     */
    external_invoice_number: string | null;
    /**
     * Whether this is a simplified supplier invoice (expense ticket). When `true`, `supplier` and `external_invoice_number` may be `null`.
     */
    is_simplified: boolean;
    /**
     * External integration key (ERP/CRM/e-commerce) mapping this document to a record in a third-party system. Free-format, unique per company, filterable via `?external_id=`. `null` when not set. Persistent synchronization key, independent of the request-level `Idempotency-Key`.
     */
    external_id: string | null;
    /**
     * Optional internal code assigned by the company for its own classification.
     */
    internal_code: string | null;
    supplier: SupplierRef | null;
    status: string;
    issued_on: string;
    /**
     * Reception date of the invoice, or `null`.
     */
    received_on: string | null;
    due_on: string | null;
    subtotal: string;
    /**
     * VAT BORNE (IVA soportado) of this expense, WITHOUT surcharge and WITHOUT withholding. Careful: on the sales-side documents (invoice, delivery note, quote, proforma) the SAME field name carries the NET aggregate `total_vat + total_surcharge − total_retention` instead. Header invariant here: `total === subtotal + taxes_total + total_surcharge − total_retention`. Read `total_vat` for a VAT figure whose meaning does not depend on the document family.
     */
    taxes_total: string;
    /**
     * Same VAT amount as `taxes_total`, published under the name the concept carries in the other four document families, so that the explicit identity `total === subtotal + total_vat + total_surcharge − total_retention` holds across all five without knowing which resource produced the body.
     */
    total_vat: string;
    /**
     * Aggregated IRPF withholding of the lines (Σ retention_amount). Header invariant: `total === subtotal + taxes_total + total_surcharge − total_retention`.
     */
    total_retention: string;
    /**
     * Aggregated equivalence surcharge of the lines (Σ surcharge_amount). It adds to the total exactly like VAT does, so it is part of the header invariant above.
     */
    total_surcharge: string;
    /**
     * Total of the expense. Two equivalent ways to reconstruct it from the published amounts, and only these two: the EXPLICIT one, identical in the five document families - `total = subtotal + total_vat + total_surcharge - total_retention` - or the one specific to this family, where `taxes_total` is the VAT alone - `total = subtotal + taxes_total + total_surcharge - total_retention`. Note that the aggregate shortcut of the sales-side families (`subtotal + taxes_total`) does NOT apply here: the same field name carries a different meaning on each side.
     */
    total: string;
    currency: string;
    /**
     * Amount already paid against this expense (derived from the payment ledger). Satisfies the invariant `paid_amount + pending_amount === total`.
     */
    paid_amount: string;
    /**
     * Outstanding balance pending payment for this expense (derived from the payment ledger).
     */
    pending_amount: string;
    /**
     * Derived payment status, NOT a persisted domain state (the model keeps 4 statuses). `overdue` derives from `pending` + `due_date < today` and prevails in presentation.
     */
    payment_status: 'pending' | 'partially_paid' | 'paid' | 'overdue';
    /**
     * Instant (ISO 8601 with offset) at which the payment that settled the purchase invoice was RECORDED in the ledger. `null` while it is not paid. Not the declared date: see `paid_date`.
     */
    paid_recorded_at: string | null;
    /**
     * Declared payment date (YYYY-MM-DD). `null` while the purchase invoice is not paid. The input field of `mark-paid` and `payments` keeps the name `paid_on`.
     */
    paid_date: string | null;
    payment_method: string | null;
    /**
     * Payment term days agreed with the supplier, or `null`.
     */
    payment_terms_days: number | null;
    /**
     * Supplier bank account. Always `null` in this version (accounts live embedded as JSON in `suppliers` without a stable identity). Follow-up `bridge-bank-account-cross-bc-supplier` will expose it as an object once Supplier promotes a read port.
     */
    bank_account: null;
    /**
     * Associated expense ledger account, or `null`.
     */
    expense_account: string | null;
    /**
     * UUID v7 of the associated expense category, or `null`.
     */
    expense_category_id: string | null;
    /**
     * Deductible percentage of the input VAT (0–100), or `null` when not set.
     */
    deductible_percentage: number | null;
    /**
     * Operation class for the input VAT of Modelo 303. Defaults to `corriente`. `isp` (domestic reverse charge, Art. 84.Uno.2 LIVA) and `intracomunitaria` are self-assessed: the buyer declares both the output VAT and the deductible input VAT.
     */
    operation_class: 'corriente' | 'bien_inversion' | 'importacion' | 'intracomunitaria' | 'isp';
    /**
     * Declarative per-document flag: whether this expense is excluded from the annual Modelo 347 report.
     */
    exclude_347: boolean;
    /**
     * Fiscal allocation period (format `YYYY-MM` or `YYYY-QN`), or `null`.
     */
    tax_period: string | null;
    /**
     * Indicates whether the invoice is subject to reverse charge.
     */
    is_reverse_charge: boolean;
    /**
     * Free classification tags (lowercase slugs `[a-z0-9-]`, ≤ 40 chars each, ≤ 30 tags). Filterable via `?tags[in]=tag1,tag2` (JSON_CONTAINS, OR semantics). Empty `[]` when there are none.
     */
    tags: Array<string>;
    /**
     * Ordered list of typed custom fields `[{field, value}]` (≤ 50). Distinct from `metadata` (a free key→value map): use `custom_fields` for structured, display-oriented integration metadata. Empty `[]` when there are none.
     */
    custom_fields: Array<CustomField>;
    /**
     * Internal notes not visible to the supplier, or `null`.
     */
    internal_notes: string | null;
    attachment: PurchaseInvoiceAttachment | null;
    lines: Array<PurchaseInvoiceLine>;
    metadata: Metadata;
    notes: string | null;
    created_at: string;
    updated_at: string;
};

/**
 * PurchaseInvoiceAttachment
 *
 * File attached to the expense (PDF or image). `null` when there is no attachment.
 */
export type PurchaseInvoiceAttachment = {
    /**
     * Original name of the uploaded file.
     */
    filename: string;
    /**
     * MIME type of the file (e.g. `application/pdf`).
     */
    mime_type: string;
    /**
     * File size in bytes.
     */
    size_bytes: number;
    /**
     * Relative download URL of the attachment (`/v1/companies/{company}/purchase-invoices/{purchase_invoice}/file`).
     */
    download_url: string;
};

/**
 * PurchaseInvoiceLine
 *
 * A line item on an expense.
 */
export type PurchaseInvoiceLine = {
    object: 'purchase_invoice_line';
    /**
     * Zero-based ordinal of the line within this expense, in the stable read order. Send it back on create/update to keep a line matched to its historical counterpart (measures, units and frozen cost are preserved when the physical selection and the supplier do not change). It is NOT a primary key and it grants no access to any other document.
     */
    source_line_index?: number | null;
    description: string | null;
    /**
     * Optional secondary description rendered below the line concept on document PDFs.
     */
    additional_description: string | null;
    /**
     * Billed quantity. A measured purchase line (one carrying `purchase_measurement`) returns it as a 4-decimal STRING so no precision is lost; a legacy line keeps the numeric type it has always published.
     */
    quantity: number | string;
    /**
     * Cost per billed unit, always a decimal STRING with the 4-decimal scale of its column (e.g. `"7.4000"`, `"100.0000"`), on measured (carrying `purchase_measurement`), legacy and manual lines alike: it is returned exactly as it was accepted and stored, so reading a line and sending it back never changes its cost. Derived amounts keep 2 decimals.
     */
    unit_price: string;
    /**
     * Discount percentage applied to the line (0-100) BEFORE any tax. `subtotal` is already net of it, so `unit_price` multiplied by `quantity` does NOT equal `subtotal` on a discounted line. Default 0.
     */
    discount_percent?: number;
    /**
     * Real measured quantity in the base unit, as a decimal string, for a variable-measure presentation (weighed goods). `null` when the line does not require one. It is reconstructed from the stored base quantity, never recomputed against the live catalog.
     */
    confirmed_base_quantity?: string | null;
    /**
     * Measured-purchase block. `null` on a legacy or manual line, which keeps its previous `quantity` × `unit_price` semantics. On write only `package_quantity` and `cost_basis` are accepted; the remaining fields are DERIVED by the server and are never taken from the client.
     */
    purchase_measurement?: {
        /**
         * Physical number of packages/presentations received, as a decimal string (e.g. `"3.0000"` boxes). `null` when the purchase is not counted in packages — it means neither one nor zero.
         */
        package_quantity: string | null;
        /**
         * Derived. Billed quantity expressed in `billing_unit_code` (e.g. `"6.0000"` kg for three 2 kg boxes).
         */
        billing_quantity: string;
        /**
         * Derived. UN/ECE code of the unit the cost applies to (`KGM`, `LTR`, `C62`, …).
         */
        billing_unit_code: string;
        /**
         * Derived. Factor, at scale 6, between the billing unit and the base unit of the product.
         */
        billing_conversion_factor: string;
        /**
         * Derived. Cost per billing unit, as a decimal string (e.g. `"7.4000"` per kg). A confirmed `"0.0000"` is a free line, not an unknown cost.
         */
        unit_cost: string;
        /**
         * Which unit the cost is quoted in: the supplier offer unit (requires an applicable offer), the product base unit (factor 1, manual cost) or a fixed presentation (manual cost per presentation).
         */
        cost_basis: 'offer_unit' | 'base_unit' | 'presentation_unit';
    } | null;
    tax_rate: number;
    /**
     * IRPF withholding percentage applied to the supplier (0–100). Default 0.
     */
    retention_rate: number;
    /**
     * Equivalence surcharge (recargo de equivalencia) percentage paid to the retail supplier (0–100). Default 0. Only the legal VAT-surcharge pairs are accepted (21→5.2, 10→1.4, 4→0.5).
     */
    surcharge_rate: number;
    subtotal: string;
    taxes: string;
    /**
     * Withholding amount of the line (`subtotal * retention_rate / 100`). The line total follows `subtotal + taxes − retention_amount + surcharge_amount`.
     */
    retention_amount: string;
    /**
     * Equivalence surcharge amount of the line (`subtotal * surcharge_rate / 100`). Default 0.
     */
    surcharge_amount: string;
    /**
     * Whether the line VAT is deductible. It does not change the amount paid, but a `false` line is excluded from the deductible input VAT of Modelo 303 (boxes [28]-[37]).
     */
    vat_deductible: boolean;
    total: string;
    /**
     * LIVA exemption cause (E1–E6) or non-subjection cause (N1/N2) declared for this line, or null when the line does not declare one.
     */
    exemption_reason?: string | null;
    /**
     * Indirect tax regime override of the supplier line: `iva`/`igic`/`ipsi` when set per-document (precedence override>zone), otherwise `null`. Writable on create/update; the document must be homogeneous (a single non-null regime across all lines, 422 otherwise).
     */
    indirect_tax_regime?: 'iva' | 'igic' | 'ipsi' | null;
    product: ProductRef | null;
    variant: {
        id: string;
        name: string | null;
    } | null;
    presentation: {
        id: string;
        name: string | null;
        mode: string | null;
    } | null;
    supplier_offer_id: string | null;
    item_kind: string | null;
    commercial_unit_code: string | null;
    base_unit_code: string | null;
    conversion_factor: string | null;
    base_quantity: string | null;
    price_source: string | null;
    price_unit_code: string | null;
    /**
     * Commercial combination frozen on the line, or `null` when the line was not sold or bought through one (legacy product, manual line).
     */
    configuration: {
        id: string;
        name: string | null;
        signature: string | null;
    } | null;
    /**
     * Configurable options frozen on the line, in printing order. Always an array, `[]` included.
     */
    options: Array<{
        group: {
            id: string;
            name: string | null;
        };
        value: {
            id: string;
            name: string | null;
        };
        /**
         * Adjustment of the chosen value per commercial unit. `null` means the value does not change the price — NOT the same as adjusting by `0`.
         */
        price_adjustment: string | null;
        /**
         * Whether that amount was actually ADDED to the unit price. `false` when an exact price (price-list entry, combination price or a manually typed unit price) already absorbed it.
         */
        applied: boolean;
    }>;
    /**
     * Monetary semantics of the frozen price: `per_base_unit` (converted once by the presentation factor) or `per_commercial_unit` (never converted). `null` when the line carries no catalog price context.
     */
    price_semantics: 'per_base_unit' | 'per_commercial_unit' | null;
    /**
     * Sum of the adjustments of the chosen option values, as a decimal string.
     */
    price_adjustment_total: string | null;
    /**
     * TRI-STATE, and `null` is NOT `false`. `true`: the frozen price already includes the option adjustments. `false`: they were added on top. `null`: it could not be determined.
     */
    option_adjustments_absorbed: boolean | null;
};

/**
 * PurchaseInvoiceMatch
 *
 * The three-way match of a supplier invoice, read from the INVOICE: the resulting status, the purchase order it is linked to, and line by line what was ordered, what was received and what is being invoiced, with the typed reason of every deviation and the figure that justifies it. It is what the three match write operations return, so the integrator sees the resulting state without a second call.
 */
export type PurchaseInvoiceMatch = {
    /**
     * Always `purchase_invoice_match`.
     */
    object: 'purchase_invoice_match';
    /**
     * Match status of the invoice: `not_applicable` when it is not linked to any order, `pending` while it has not been evaluated, `matched` when everything adds up, `deviation` when it does not, and `rejected` when the deviation was rejected. Accepting a deviation resolves it to `matched`, and that leaves the ORDER invoiced — a terminal status no operation of this API reopens.
     */
    match_status: 'not_applicable' | 'pending' | 'matched' | 'deviation' | 'rejected';
    /**
     * Opaque identifier (UUID v7) of the linked purchase order, or `null` when the invoice is not linked to one.
     */
    purchase_order_id: string | null;
    /**
     * Number of that order, or `null` when there is none.
     */
    purchase_order_number: string | null;
    /**
     * Whether any line carries a deviation reason. It is the question the decision hangs on, published as a boolean so a client does not have to walk the lines to ask it.
     */
    has_deviation: boolean;
    /**
     * One entry per matched line, with the three quantities in BASE units, the two costs per base unit, and the deviation reasons of that line. A line with no reason is a line that adds up.
     */
    lines: Array<PurchaseInvoiceMatchLine>;
    /**
     * How many lines of the invoice were left OUT of the match because they carry no catalog identity (shipping, a free-text concept). They are not deviations and they are not invented a counterpart: they are declared here so that a total that does not add up has a visible explanation instead of a silent one.
     */
    excluded_line_count: number;
};

/**
 * PurchaseInvoiceMatchDeviation
 *
 * ONE reason why a line does not match, with the figure that justifies it. The classification alone is not actionable — "there is a price deviation" can neither be accepted nor argued — so every reason always carries the three magnitudes: the expected one, the invoiced one and the signed difference between them. Tolerance is applied BEFORE classifying, so a reason with a zero difference never travels.
 */
export type PurchaseInvoiceMatchDeviation = {
    /**
     * Typed reason. Four compare a line against its counterpart on the order (`price_*` against the agreed cost per base unit, `quantity_*` against what was actually received); the other two exist because a line may have NO counterpart, which is a deviation just as real: `line_not_ordered` (the invoice brings an item the order does not contain) and `line_not_invoiced` (the order has a received line the invoice does not cover).
     */
    reason: 'price_above' | 'price_below' | 'quantity_above' | 'quantity_below' | 'line_not_ordered' | 'line_not_invoiced';
    /**
     * Expected magnitude — what was agreed with the supplier or what actually arrived at the warehouse, depending on the reason — as a decimal string. Quantities carry four decimal places and costs per base unit six: the scale is chosen by the FAMILY of the reason, so both sides of a comparison always share it.
     */
    expected: string;
    /**
     * Magnitude the supplier is claiming, as a decimal string with the same scale as `expected`.
     */
    invoiced: string;
    /**
     * Signed difference, always `invoiced - expected`: POSITIVE on the `*_above` reasons and on `line_not_ordered`, NEGATIVE on the `*_below` ones and on `line_not_invoiced`. Never zero.
     */
    difference: string;
};

/**
 * PurchaseInvoiceMatchLine
 *
 * One line of the supplier invoice seen from the three-way match, against its counterpart on the order. Quantities are in BASE units with four decimal places and costs per base unit with six, which is what lets buying in boxes of twelve and invoicing in units NOT read as a price deviation.
 */
export type PurchaseInvoiceMatchLine = {
    /**
     * Opaque identifier (UUID v7) of the catalog item of the line.
     */
    product_id: string;
    /**
     * Opaque identifier (UUID v7) of the variant, or `null` when the item has none.
     */
    product_variant_id: string | null;
    /**
     * Code of the BASE unit every quantity of this entry is expressed in.
     */
    base_unit_code: string;
    /**
     * Quantity ordered, in base units, as a decimal string with FOUR decimal places.
     */
    ordered_base_quantity: string;
    /**
     * Quantity received in POSTED goods receipts, in base units, with the same scale. It is what the invoiced quantity is compared against: what is invoiced is what arrived, and comparing against what was ordered would flag every legitimate partial delivery.
     */
    received_base_quantity: string;
    /**
     * Quantity the supplier is invoicing, in base units, with the same scale.
     */
    invoiced_base_quantity: string;
    /**
     * Cost of one BASE unit agreed on the order (`unit_cost / conversion_factor`), as a decimal string with SIX decimal places.
     */
    agreed_cost_per_base_unit: string;
    /**
     * Cost of one BASE unit the supplier is invoicing, with the same six-decimal scale.
     */
    invoiced_cost_per_base_unit: string;
    /**
     * Typed reasons why this line does not add up, each with its figures. Empty when the line matches within tolerance.
     */
    deviations: Array<PurchaseInvoiceMatchDeviation>;
};

/**
 * PurchaseInvoicePayment
 *
 * A single payment recorded against a purchase invoice (payment ledger entry). Listed by `GET /v1/companies/{company}/purchase-invoices/{purchase_invoice}/payments` and returned by `POST` on the same path.
 */
export type PurchaseInvoicePayment = {
    /**
     * Opaque UUID v7 of the payment.
     */
    id: string;
    /**
     * String identifying the object type. Always `purchase_invoice_payment`.
     */
    object: 'purchase_invoice_payment';
    /**
     * Payment amount as a string with two decimal places (Stripe-style).
     */
    amount: string;
    /**
     * Payment date (YYYY-MM-DD). Renamed from `paid_on`, which is no longer emitted; the INPUT field of `POST` keeps the old name on purpose.
     */
    paid_date: string;
    /**
     * Payment method (backing value of the Shared enum `PaymentMethod`, e.g. `bank_transfer`).
     */
    payment_method: string;
    /**
     * Internal bank account the payment was settled into, or `null`.
     */
    bank_account_id: number | null;
    /**
     * Payment reference/operation number. `null` if not provided.
     */
    reference: string | null;
    /**
     * Internal notes for the payment. `null` if not provided.
     */
    notes: string | null;
    /**
     * Whether the payment has been reverted. A reverted payment stays in the ledger but stops counting towards `paid_amount`/`pending_amount` — read this flag, do not infer the state from absence.
     */
    is_reversed: boolean;
    /**
     * When the payment was reverted (ISO 8601), or `null` while it is in force.
     */
    reversed_at: string | null;
    /**
     * Reason the payment was reverted, from the closed catalog. `null` while the payment is in force.
     */
    reversal_reason: string | null;
    /**
     * Human-readable label of the reversal reason (Spanish), or `null`.
     */
    reversal_reason_text: string | null;
    /**
     * Free-text remark recorded with the reversal, or `null`.
     */
    reversal_note: string | null;
    /**
     * When the payment was recorded (ISO 8601).
     */
    created_at: string;
};

/**
 * PurchaseInvoiceStats
 *
 * Aggregated metrics (KPIs) of the expenses of the authenticated company: total, count by status and accumulated amounts. `overdue` is a derived condition (`pending` + past due date), not a persisted status.
 */
export type PurchaseInvoiceStats = {
    object: 'purchase_invoice_stats';
    /**
     * Total number of expenses.
     */
    total_invoices: number;
    /**
     * Invoice count by status (key = status, value = number of invoices). Keys: `draft`, `pending`, `paid`, `cancelled` (persisted statuses) plus `overdue` (derived KPI: overdue subset of `pending`).
     */
    by_status: {
        [key: string]: number;
    };
    /**
     * Number of invoices pending payment.
     */
    pending: number;
    /**
     * Number of draft invoices.
     */
    draft: number;
    /**
     * Number of paid invoices.
     */
    paid: number;
    /**
     * Number of cancelled invoices.
     */
    cancelled: number;
    /**
     * Number of overdue and unpaid invoices (subset of `pending` with a past due date).
     */
    overdue: number;
    /**
     * Total aggregate amount of all expenses.
     */
    total_amount: string;
    /**
     * Total amount pending payment.
     */
    pending_amount: string;
    /**
     * Total amount already paid.
     */
    paid_amount: string;
};

/**
 * PurchaseOrder
 *
 * A purchase order: the commitment to buy goods from a supplier, and the document the goods receipts and the supplier invoices that fulfil it are matched against. It is NOT a fiscal document, but unlike a sales order it takes its number when it is CREATED, so `number` is always present — even on a draft. Amounts are decimal strings with two decimal places; line quantities are decimal strings with four.
 */
export type PurchaseOrder = {
    /**
     * Opaque identifier of the purchase order, a UUID v7. Every reference of this document travels the same way: no internal numeric key is ever published.
     */
    id: string;
    /**
     * Always `purchase_order`.
     */
    object: 'purchase_order';
    /**
     * Number of the order (`PC-YYYY-N`), stamped inside the transaction that CREATES it. It is never `null`, not even while the order is a draft: this family numbers on creation, unlike the sales order, which numbers on confirmation. The sequence guarantees uniqueness and not density, so a creation that rolls back leaves a permanent gap.
     */
    number: string;
    /**
     * Lifecycle status of the order: `draft` (editable), `sent` (issued to the supplier), `confirmed` (accepted by the supplier), `partially_received` and `received` (goods arrived in part or in full), `billed` (the supplier invoice matched it) and `cancelled`. The two reception states are DERIVED from posting a goods receipt and are not destinations you can ask for, and `billed` is stamped by the three-way match from the supplier invoice. Both `billed` and `cancelled` are terminal and no operation reopens them.
     */
    status: 'draft' | 'sent' | 'confirmed' | 'partially_received' | 'received' | 'billed' | 'cancelled';
    /**
     * Label of the status in Spanish, ready to display.
     */
    status_label: string;
    /**
     * Opaque identifier (UUID v7) of the commercial contact acting as the supplier of this order.
     */
    supplier_id: string;
    /**
     * Name of the supplier as it was recorded on the order.
     */
    supplier_name: string;
    /**
     * Reference the SUPPLIER uses for this order, or `null` when none was given. It is OPTIONAL and UNIQUE per company: creating a second order with a reference that already exists is REJECTED with `409`, it does not update the first one. Two orders without a reference coexist, because two `NULL` values do not collide in a unique index.
     */
    supplier_order_reference: string | null;
    /**
     * Opaque identifier (UUID v7) of the warehouse the goods are expected at, or `null` when the order is not tied to one. Each line may override it.
     */
    warehouse_id: string | null;
    /**
     * Name of that warehouse, or `null` when there is none.
     */
    warehouse_name: string | null;
    /**
     * Date of the order, as a plain calendar date.
     */
    order_date: string;
    /**
     * Date the goods are expected to arrive, as a plain calendar date, or `null` when none was agreed.
     */
    expected_date: string | null;
    /**
     * Free-text notes of the order, or `null` when there are none.
     */
    notes: string | null;
    /**
     * Amount of the order before taxes, as a decimal string with two decimal places.
     */
    subtotal: string;
    /**
     * Input VAT (IVA soportado) of the order: sum of the VAT of its lines.
     */
    tax_amount: string;
    /**
     * Withholding (retencion de IRPF) of the order: sum of the withholding of its lines, as a POSITIVE amount that SUBTRACTS from the total.
     */
    retention_amount: string;
    /**
     * Equivalence surcharge (recargo de equivalencia) of the order: sum of the surcharge of its lines. It ADDS to the total exactly like VAT does.
     */
    surcharge_amount: string;
    /**
     * Total of the order, reconstructed with the identity shared by every document family: `total = subtotal + tax_amount + surcharge_amount - retention_amount`.
     */
    total: string;
    /**
     * Whether every line has already received the whole quantity that was ordered. It is DERIVED from the posted goods receipts: no operation writes it.
     */
    fully_received: boolean;
    /**
     * Lines of the order, each with the quantity in its PURCHASE unit, the conversion factor to the base unit, the received and pending quantities derived from the posted receipts, and the ledger of the receipts that consumed it.
     */
    lines: Array<PurchaseOrderLine>;
    /**
     * Goods receipts registered against this order, including the cancelled ones: what an order received is history and a cancelled receipt is part of it. Empty while nothing has arrived.
     */
    receipts: Array<GoodsReceipt>;
    /**
     * When the order was created (ISO 8601).
     */
    created_at: string | null;
    /**
     * When the order was last modified (ISO 8601).
     */
    updated_at: string | null;
};

/**
 * PurchaseOrderEmailDelivery
 *
 * Acknowledgement that the purchase order was accepted and queued for delivery to the supplier by email.
 */
export type PurchaseOrderEmailDelivery = {
    /**
     * Always `purchase_order_email_delivery`.
     */
    object: 'purchase_order_email_delivery';
    /**
     * Opaque identifier of the purchase order that was queued for sending, a UUID v7. It is also the key with which the delivery is located afterwards on the email deliveries surface.
     */
    purchase_order_id: string;
    /**
     * Always `queued`: the acknowledgement states that the email was accepted and queued, never that it was delivered. Delivery is observed afterwards through the email deliveries surface.
     */
    status: 'queued';
};

/**
 * PurchaseOrderLine
 *
 * A line of a purchase order. It is the only line of the API that carries TWO units at once: the PURCHASE unit that was agreed with the supplier (a box, a pallet) and the BASE unit of the catalog item, joined by the conversion factor frozen on the line. Everything that later enters the warehouse is measured in the base unit, and everything the supplier invoices is measured in the purchase unit, so both travel side by side instead of being recomputed on each screen.
 */
export type PurchaseOrderLine = {
    /**
     * Always `purchase_order_line`.
     */
    object: 'purchase_order_line';
    /**
     * Opaque identifier (UUID v7) of the line. The line sub-resource edits and deletes it by this identifier, and a goods receipt names the lines it receives with it.
     */
    id: string;
    /**
     * Opaque identifier (UUID v7) of the catalog item bought on this line. A purchase order line always names a catalog item: free-text lines do not exist in this family, because what arrives at the warehouse has to be something the warehouse knows.
     */
    product_id: string;
    /**
     * Opaque identifier (UUID v7) of the variant, or `null` when the item has none.
     */
    product_variant_id: string | null;
    /**
     * Concept of the line, frozen when the line was added.
     */
    description: string;
    /**
     * Code the SUPPLIER uses for this item, copied from its offer, or `null` when the offer declares none. It is what lets the supplier read the order without translating the catalog.
     */
    supplier_sku: string | null;
    /**
     * Code of the unit the item is BOUGHT in (the one of the supplier offer): the unit `quantity` is expressed in.
     */
    purchase_unit_code: string;
    /**
     * How many BASE units one purchase unit holds, as a decimal string with SIX decimal places. It is FROZEN on the line when the line is added: a later change of the supplier offer does not move what was already agreed, which is what makes the receipt of an old order convert with the factor that was pacted and not with the current one.
     */
    conversion_factor: string;
    /**
     * Quantity ordered, in the PURCHASE unit, as a decimal string with FOUR decimal places. Quantities travel as strings and not as numbers because they are the figures a partial receipt and the three-way match use to decide what is left, and a binary float turns that arithmetic into a line nobody can close.
     */
    quantity: string;
    /**
     * The same quantity expressed in the BASE unit of the item (`quantity * conversion_factor`), with the same four-decimal scale.
     */
    base_quantity: string;
    /**
     * Quantity already received, accumulated, in the PURCHASE unit, with the same four-decimal scale. No public operation writes it: it moves when a goods receipt is POSTED, and a cancelled receipt does not count.
     */
    received_quantity: string;
    /**
     * Quantity still to receive, DERIVED as `quantity - received_quantity` with a floor of zero, in the PURCHASE unit. It is the figure a new receipt is checked against: no receipt may exceed it.
     */
    pending_quantity: string;
    /**
     * The received quantity expressed in the BASE unit, with the same four-decimal scale. It is the figure the warehouse ledger moves and the one the three-way match compares against the invoice.
     */
    received_base_quantity: string;
    /**
     * The pending quantity expressed in the BASE unit, with the same four-decimal scale.
     */
    pending_base_quantity: string;
    /**
     * Cost agreed for ONE purchase unit, as a decimal string with FOUR decimal places — not two. Its column is `decimal(14,4)` and it is the figure margins are computed from, so it is published with the scale it is stored in; truncating it to two decimals would change the published cost. It is copied from the supplier offer when the line is added.
     */
    unit_cost: string;
    /**
     * VAT percentage applied to the line (0-100). A percentage is not money, so it travels as a number.
     */
    tax_rate: number;
    /**
     * IRPF withholding percentage applied to the line (0-100). Its amount subtracts from the total.
     */
    retention_rate: number;
    /**
     * Equivalence surcharge percentage applied to the line (0-100). Its amount adds to the total.
     */
    surcharge_rate: number;
    /**
     * Amount of the line before taxes, as a decimal string with two decimal places.
     */
    subtotal: string;
    /**
     * VAT amount of the line.
     */
    tax_amount: string;
    /**
     * Withholding amount of the line, as a POSITIVE amount that subtracts from the line total.
     */
    retention_amount: string;
    /**
     * Equivalence surcharge amount of the line.
     */
    surcharge_amount: string;
    /**
     * Total of the line: `subtotal + tax_amount + surcharge_amount - retention_amount`.
     */
    total: string;
    /**
     * Opaque identifier (UUID v7) of the warehouse this line is expected at; it inherits the one of the order when it is not set.
     */
    warehouse_id: string | null;
    /**
     * Ledger of the POSTED goods receipts that took quantity away from this line. The accumulated figures above are a number; this is the list of receipts behind them, so `received 7 of 10` stops being a figure without an author. It is populated by the line sub-resource (`GET .../purchase-orders/{purchase_order}/lines`), which is the operation that exists to answer that question, and arrives EMPTY on the order detail: resolving it costs one extra query per order and only the operation that needs it pays for it.
     */
    receipts: Array<PurchaseOrderLineReceipt>;
};

/**
 * PurchaseOrderLineReceipt
 *
 * One reception of a purchase order line: the goods receipt that took a quantity away from it, and how much. Only POSTED receipts appear here — a cancelled one gave the quantity back and counting it would say the goods are in the warehouse when they are not. The sum of these quantities matches EXACTLY the `received_quantity` of the line.
 */
export type PurchaseOrderLineReceipt = {
    /**
     * Always `purchase_order_line_receipt`.
     */
    object: 'purchase_order_line_receipt';
    /**
     * Opaque identifier (UUID v7) of the goods receipt that took the quantity, so the line can be reconciled against it.
     */
    goods_receipt_id: string;
    /**
     * Number of that goods receipt, so the reconciliation does not need a second call to become readable.
     */
    goods_receipt_number: string;
    /**
     * Date the goods were received, as a plain calendar date.
     */
    received_on: string;
    /**
     * Quantity of this reception in the PURCHASE unit of the line, as a decimal string with FOUR decimal places.
     */
    quantity: string;
    /**
     * The same quantity in the BASE unit of the item, converted with the factor FROZEN on the line, with the same four-decimal scale.
     */
    base_quantity: string;
};

/**
 * PurchaseOrderMatch
 *
 * The three-way match of a purchase order, read from the ORDER: what was ordered, what was actually received and what the supplier has invoiced, line by line, plus the supplier invoices linked to it. Returned by `GET /v1/companies/{company}/purchase-orders/{purchase_order}/match`. An order with no linked invoice is not an error: it answers `not_applicable` with an empty list of invoices. The line-by-line DETAIL of a deviation lives on the surface anchored to the INVOICE, which is where it is resolved.
 */
export type PurchaseOrderMatch = {
    /**
     * Always `purchase_order_match`.
     */
    object: 'purchase_order_match';
    /**
     * Opaque identifier (UUID v7) of the order this match belongs to.
     */
    purchase_order_id: string;
    /**
     * Number of that order.
     */
    purchase_order_number: string;
    /**
     * Match status of the SET of linked invoices: `not_applicable` when there is none, `deviation` as soon as ONE of them deviates (a deviation is not compensated by an invoice that adds up), the shared status when all of them agree, and `pending` on any other mix — the match of the order is not settled while one of its invoices is not.
     */
    match_status: 'not_applicable' | 'pending' | 'matched' | 'deviation' | 'rejected';
    /**
     * Whether the set is in deviation. It is `match_status === "deviation"` seen as a boolean, published so a client does not have to compare tokens to decide whether to raise an alert.
     */
    has_deviation: boolean;
    /**
     * One entry per line of the ORDER, with the three quantities that describe the match. Always in the BASE unit of the item: ordering in boxes of twelve and invoicing in units must not read as a deviation.
     */
    lines: Array<PurchaseOrderMatchLine>;
    /**
     * Supplier invoices linked to this order. Empty when none has been linked yet.
     */
    invoices: Array<PurchaseOrderMatchInvoice>;
};

/**
 * PurchaseOrderMatchInvoice
 *
 * A supplier invoice linked to the purchase order, with its own match status: the order-level status is derived from these, so they are published rather than summarised away.
 */
export type PurchaseOrderMatchInvoice = {
    /**
     * Opaque identifier (UUID v7) of the supplier invoice.
     */
    purchase_invoice_id: string;
    /**
     * Number of the supplier invoice.
     */
    number: string;
    /**
     * Match status of THIS invoice against the order.
     */
    match_status: 'not_applicable' | 'pending' | 'matched' | 'deviation' | 'rejected';
    /**
     * Total of the supplier invoice, as a decimal string with two decimal places.
     */
    total: string;
};

/**
 * PurchaseOrderMatchLine
 *
 * One line of the order seen from the three-way match: how much was ordered, how much actually arrived and how much the supplier has invoiced. The three quantities are in the BASE unit of the item and share the same four-decimal scale, so they can be subtracted from one another without converting anything.
 */
export type PurchaseOrderMatchLine = {
    /**
     * Opaque identifier (UUID v7) of the order line this entry reports on.
     */
    purchase_order_line_id: string;
    /**
     * Opaque identifier (UUID v7) of the catalog item of the line.
     */
    product_id: string;
    /**
     * Opaque identifier (UUID v7) of the variant, or `null` when the item has none.
     */
    product_variant_id: string | null;
    /**
     * Concept of the line, as it was frozen on the order.
     */
    description: string;
    /**
     * Code of the BASE unit the three quantities are expressed in.
     */
    base_unit_code: string;
    /**
     * Quantity ordered, in the base unit, as a decimal string with FOUR decimal places.
     */
    ordered_base_quantity: string;
    /**
     * Quantity received in POSTED goods receipts, in the base unit, with the same scale. A cancelled receipt does not count.
     */
    received_base_quantity: string;
    /**
     * Quantity invoiced by the linked supplier invoices, in the base unit, with the same scale. Zero while nothing has been invoiced.
     */
    invoiced_base_quantity: string;
};

/**
 * PurchaseOrderStats
 *
 * Aggregated headline figures of the purchase orders of the authenticated company. Returned by `GET /v1/companies/{company}/purchase-orders/stats`, wrapped in `{ "data": PurchaseOrderStats }`.
 */
export type PurchaseOrderStats = {
    /**
     * Always `purchase_order_stats`.
     */
    object: 'purchase_order_stats';
    /**
     * Number of purchase orders of the company. It is a COUNT, not money: it does not travel with the two decimals of an amount, unlike `total_amount` of this very object.
     */
    total_count: number;
    /**
     * Number of orders per status, keyed by the token of the closed catalog. It carries one entry per status INCLUDING the ones at zero, so a client never has to tell `zero` apart from `did not come`.
     */
    count_by_status: {
        [key: string]: number;
    };
    /**
     * Accumulated total of every purchase order of the company, as a decimal string with two decimal places.
     */
    total_amount: string;
    /**
     * Amount already committed to suppliers whose goods have not arrived in full: orders from `sent` onwards that are not fully received. A draft does not count, because it commits nothing.
     */
    pending_to_receive_amount: string;
    /**
     * Amount of goods already received that the supplier has not invoiced yet. It is the other half of the picture: what is owed but not yet claimed.
     */
    pending_to_bill_amount: string;
};

/**
 * PurchaseOrderStatusItem
 *
 * A purchase order status from the closed catalog, with its label, its colour and what it allows. Returned by `GET /v1/companies/{company}/purchase-orders/statuses` as a flat list. The three permissions are the contract that spares the integrator a round of trial and error: they say, BEFORE trying, which statuses admit editing the order or deleting it.
 */
export type PurchaseOrderStatusItem = {
    /**
     * Always `purchase_order_status_item`.
     */
    object: 'purchase_order_status_item';
    /**
     * Status token. It is the identity of the status: a token of a closed catalog, not a row of any table.
     */
    value: 'draft' | 'sent' | 'confirmed' | 'partially_received' | 'received' | 'billed' | 'cancelled';
    /**
     * Label of the status in Spanish, ready to display.
     */
    label: string;
    /**
     * Suggested colour token for rendering the status.
     */
    color: string;
    /**
     * Whether the status admits editing the contents of the order. Only a draft does.
     */
    can_edit: boolean;
    /**
     * Whether the status admits deleting the order. Only a draft does: an order already sent to the supplier is cancelled, not deleted, so the trace survives.
     */
    can_delete: boolean;
    /**
     * Whether the status admits converting the order into another document. It is `false` in every status today, and that is the answer of the domain and not a gap: what closes a purchase order is the three-way match against the supplier invoice, which is not a conversion. The field is published anyway so the catalog has one single shape across the six document families.
     */
    can_convert: boolean;
};

/**
 * PurchaseScan
 */
export type PurchaseScan = {
    id: string;
    version: number;
    source: 'upload' | 'email' | 'api';
    status: 'received' | 'queued' | 'processing' | 'needs_review' | 'duplicate' | 'failed' | 'auto_created' | 'created' | 'archived';
    original_filename: string;
    mime_type: string;
    page_count: number;
    received_at: string;
    uploaded_by: {
        name: string | null;
    };
    supplier_id: string | null;
    supplier_name: string | null;
    document_number: string | null;
    issue_date: string | null;
    currency: string | null;
    total: string | null;
    /**
     * Number of issues still pending review: one per field, supplier identity counted once, 0 before the first extraction.
     */
    issue_count: number;
    available_actions: Array<'save_review' | 'convert' | 'link_existing' | 'override_duplicate' | 'retry' | 'replace_source' | 'archive' | 'restore' | 'download_source' | 'view_purchase_invoice'>;
    purchase_invoice_id: string | null;
    last_error: {
        code: 'ocr_temporarily_unavailable' | 'scan_storage_unavailable' | 'file_safety_unavailable' | 'inbound_provider_unavailable' | 'resource_locked' | 'queue_delivery_failed' | 'purchase_scanner_disabled' | 'ocr_company_quota_exceeded' | 'module_upgrade_required' | 'unsupported_scan_format' | 'unsupported_purchase_document_type' | 'unsafe_scan_file' | 'scan_page_limit_exceeded' | 'purchase_scanner_internal_error';
        recoverable: boolean;
        message: string;
    } | null;
    /**
     * When set, the scan is waiting for the company daily OCR quota to reset; it will be retried automatically.
     */
    deferred_until: string | null;
    deferred_reason: 'ocr_daily_quota_reached' | null;
    file_revision: number;
    extraction_revision: number | null;
    bytes: number;
    updated_at: string;
    preview: {
        url: string | null;
        source_url: string;
        page_count: number;
    };
    review: {
        version: number;
        extraction_revision: number | null;
    };
    extraction: {
        supplier_id: PurchaseScanExtractedField;
        supplier_name: PurchaseScanExtractedField;
        supplier_tax_id: PurchaseScanExtractedField;
        is_simplified: PurchaseScanExtractedField;
        document_number: PurchaseScanExtractedField;
        issue_date: PurchaseScanExtractedField;
        reception_date: PurchaseScanExtractedField;
        due_date: PurchaseScanExtractedField;
        currency: PurchaseScanExtractedField;
        payment_method: PurchaseScanExtractedField;
        expense_category: PurchaseScanExtractedField;
        operation_class: PurchaseScanExtractedField;
        notes: PurchaseScanExtractedField;
        issuer_tax_id: PurchaseScanExtractedField;
        recipient_tax_id: PurchaseScanExtractedField;
        totals_confirmed: PurchaseScanExtractedField;
        extraction_confirmed: PurchaseScanExtractedField;
        totals: {
            subtotal: PurchaseScanExtractedField;
            tax: PurchaseScanExtractedField;
            retention: PurchaseScanExtractedField;
            surcharge: PurchaseScanExtractedField;
            total: PurchaseScanExtractedField;
        };
        printed_totals: {
            subtotal: PurchaseScanExtractedField;
            tax: PurchaseScanExtractedField;
            retention: PurchaseScanExtractedField;
            surcharge: PurchaseScanExtractedField;
            total: PurchaseScanExtractedField;
        };
        detected_document_type?: PurchaseScanExtractedField;
    };
    lines: Array<{
        line_id: string;
        fields: {
            description: PurchaseScanExtractedField;
            additional_description: PurchaseScanExtractedField;
            supplier_sku?: PurchaseScanExtractedField;
            unit_code?: PurchaseScanExtractedField;
            price_unit_code?: PurchaseScanExtractedField;
            package_quantity?: PurchaseScanExtractedField;
            measured_base_quantity?: PurchaseScanExtractedField;
            quantity: PurchaseScanExtractedField;
            unit_price: PurchaseScanExtractedField;
            discount_rate: PurchaseScanExtractedField;
            tax_rate: PurchaseScanExtractedField;
            retention_rate: PurchaseScanExtractedField;
            surcharge_rate: PurchaseScanExtractedField;
            vat_deductible: PurchaseScanExtractedField;
            indirect_tax_regime: PurchaseScanExtractedField;
            exemption_reason: PurchaseScanExtractedField;
            line_subtotal: PurchaseScanExtractedField;
            tax_amount: PurchaseScanExtractedField;
            retention_amount: PurchaseScanExtractedField;
            surcharge_amount: PurchaseScanExtractedField;
            line_total: PurchaseScanExtractedField;
        };
        catalog_selection?: PurchaseScanCatalogSelection;
    }>;
    issues: Array<{
        code: string;
        severity?: 'info' | 'warning' | 'error';
        field?: string | null;
        line_id?: string | null;
        message?: string | null;
    }>;
    duplicate: {
        type?: string;
        candidate_id?: string | null;
        candidate_purchase_invoice_id?: string | null;
        matched_fields?: Array<string>;
        override_authorized?: boolean;
        linked?: boolean;
        override_reason?: string | null;
        resolved_at?: string | null;
    } | null;
    /**
     * The 50 most recent processing attempts, newest first. `attempts_total` holds how many there are in all.
     */
    attempts: Array<{
        id: string;
        invocation_number?: number;
        status: string;
        started_at?: string;
        finished_at?: string;
        latency_ms?: number;
        pages?: number;
        cache_hit?: boolean;
        error_code?: string;
        error_recoverable?: boolean;
    }>;
    /**
     * Total number of processing attempts, including those not listed in `attempts`.
     */
    attempts_total: number;
    /**
     * The 50 most recent audit events, newest first. `audit_total` holds how many there are in all.
     */
    audit: Array<{
        id: string;
        action: string;
        before_version?: number;
        after_version?: number;
        correlation_id?: string;
        occurred_at?: string;
    }>;
    /**
     * Total number of audit events, including those not listed in `audit`.
     */
    audit_total: number;
    linked_purchase_invoice: {
        id: string;
    } | null;
    supplier_resolution: {
        status: 'matched' | 'new_candidate' | 'ambiguous' | 'incomplete' | 'invalid' | 'inactive' | 'role_required' | 'conflict';
        reason_code: string | null;
        scan_version: number;
        supplier_id: string | null;
        candidates: Array<{
            id: string;
            name: string;
            tax_id: string | null;
        }>;
        can_create: boolean;
        blocked_reason: string | null;
    } | null;
    conversion_readiness: {
        can_convert: boolean;
        requires_supplier_creation: boolean;
        blocking_fields: Array<string>;
    } | null;
    /**
     * Whether the original file is still retained. It does not depend on the API key permissions: `download_source` can be missing from `available_actions` while this is true.
     */
    source_retained: boolean;
    review_fields: {
        document: Array<'supplier_id' | 'supplier_name' | 'supplier_tax_id' | 'is_simplified' | 'document_number' | 'issue_date' | 'reception_date' | 'due_date' | 'currency' | 'payment_method' | 'expense_category' | 'operation_class' | 'notes' | 'issuer_tax_id' | 'recipient_tax_id' | 'totals_confirmed' | 'extraction_confirmed'>;
        read_only: Array<'detected_document_type'>;
        totals: Array<'subtotal' | 'tax' | 'retention' | 'surcharge' | 'total'>;
        line: Array<'description' | 'additional_description' | 'supplier_sku' | 'unit_code' | 'price_unit_code' | 'package_quantity' | 'measured_base_quantity' | 'quantity' | 'unit_price' | 'discount_rate' | 'tax_rate' | 'retention_rate' | 'surcharge_rate' | 'vat_deductible' | 'indirect_tax_regime' | 'exemption_reason' | 'line_subtotal' | 'tax_amount' | 'retention_amount' | 'surcharge_amount' | 'line_total'>;
        exemption_reasons: Array<'E1' | 'E2' | 'E3' | 'E4' | 'E5' | 'E6' | 'N1' | 'N2'>;
        /**
         * Accepted values of the `operation_class` review field.
         */
        operation_classes: Array<string>;
    };
    automation: {
        /**
         * Business rule that stopped the automatic conversion and sent the scan back to review, or null.
         */
        rejection_code: string | null;
    };
    can_save_review: boolean;
    can_convert: boolean;
    can_link_existing: boolean;
    can_override_duplicate: boolean;
    can_retry: boolean;
    can_replace_source: boolean;
    can_archive: boolean;
    can_restore: boolean;
    can_download_source: boolean;
    can_view_purchase_invoice: boolean;
};

/**
 * PurchaseScanCatalogSelection
 *
 * Catalog selection made by a person during review, never by OCR. In the review request, omit it to keep the current selection and send null to unlink the line. Company ownership is verified when the review is saved; the combination is resolved when the scan is converted.
 */
export type PurchaseScanCatalogSelection = {
    product_id: string;
    variant_id?: string | null;
    presentation_id?: string | null;
    supplier_offer_id?: string | null;
    configuration_id?: string | null;
    configuration_signature?: string | null;
    /**
     * Chosen option values, at most one per option group.
     */
    options?: Array<{
        group_id: string;
        value_id: string;
    }> | null;
    purchase_measurement?: {
        /**
         * Decimal string greater than zero when provided.
         */
        package_quantity?: string | null;
        cost_basis: 'offer_unit' | 'base_unit' | 'presentation_unit';
    } | null;
    /**
     * Decimal string greater than zero when provided.
     */
    confirmed_base_quantity?: string | null;
} | null;

/**
 * PurchaseScanEmail
 */
export type PurchaseScanEmail = {
    id: string;
    sender: string;
    subject: string | null;
    received_at: string;
    /**
     * pending while the attachments are still being ingested; parked when the sender is not allowlisted or fails SPF/DKIM/DMARC authentication (no scan is created).
     */
    result: 'pending' | 'processed' | 'partially_processed' | 'no_compatible_attachments' | 'parked' | 'rejected' | 'failed';
    /**
     * Why the email was parked, rejected or failed; null for any other result.
     */
    reason: 'sender_not_allowlisted' | 'sender_authentication_failed' | 'sender_authentication_unavailable' | 'too_many_attachments' | 'module_inactive' | 'read_only' | 'scanner_disabled' | 'processing_failed' | null;
    /**
     * SPF/DKIM/DMARC verdict computed by the receiving server, or null when it was never evaluated.
     */
    sender_authentication: null | {
        spf: 'pass' | 'fail' | 'softfail' | 'neutral' | 'none' | 'temperror' | 'permerror';
        dkim: 'pass' | 'fail' | 'softfail' | 'neutral' | 'none' | 'temperror' | 'permerror';
        dmarc: 'pass' | 'fail' | 'softfail' | 'neutral' | 'none' | 'temperror' | 'permerror';
        alignment: 'aligned' | 'misaligned' | 'unknown';
    };
    accepted_attachments: Array<{
        filename: string;
        sha256: string;
        scan_id: string;
    }>;
    rejected_attachments: Array<{
        filename: string;
        code: string;
        message?: string;
    }>;
};

