/**
 * UpdateWeeklyScheduleRequest
 */
export type UpdateWeeklyScheduleRequest = {
    /**
     * Weekly schedule name. Optional: when omitted it keeps its current value.
     */
    name?: string;
    /**
     * Schedule mode: `validated` (assumed fulfilled) or `real_clocking` (computed from real clock entries). Optional: when omitted it keeps its current value.
     */
    mode?: 'validated' | 'real_clocking';
    /**
     * Full weekly pattern: list of days with their time ranges. Optional: when omitted the current pattern is kept; when sent it replaces the whole pattern.
     */
    week_pattern?: Array<{
        /**
         * Day of the week in ISO 8601 format (1 Monday .. 7 Sunday).
         */
        day: number;
        /**
         * Time ranges for the day (empty = rest day).
         */
        ranges: Array<{
            /**
             * Range start time (HH:MM, 00:00-23:59).
             */
            start: string;
            /**
             * Range end time (HH:MM; 24:00 is allowed as end of workday).
             */
            end: string;
            flexible?: boolean;
            required_minutes?: number | null;
        }>;
    }>;
};

